DBMS_OUTPUT.PUT_LINE(q'~      if (a.status === 'COMPLETED') bt.done += a.n; else if (a.status === 'FAILED') bt.failed += a.n; else bt.other += a.n;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    o.stats = s;~');
DBMS_OUTPUT.PUT_LINE(q'~    o.truncated = o.tasks.length < s.n;~');
DBMS_OUTPUT.PUT_LINE(q'~    o.ajh = o.job ? AJH.get(conKey(o.con, o.job)) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    const runs = o.job ? SJR.get(conKey(o.con, o.job)) || [] : [];~');
DBMS_OUTPUT.PUT_LINE(q'~    o.sjr = runs.find((j) => j.start <= o.start + 5000 && j.start + (j.secs + 5) * 1000 >= o.start) || null;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh) {~');
DBMS_OUTPUT.PUT_LINE(q'~      o.window = { name: o.ajh.window, start: o.ajh.winStart, end: o.ajh.winStart + o.ajh.winSecs * 1000, secs: o.ajh.winSecs };~');
DBMS_OUTPUT.PUT_LINE(q'~    } else {~');
DBMS_OUTPUT.PUT_LINE(q'~      const w = WINS.find((w) => w.con === o.con && w.start <= o.start && o.start < w.end);~');
DBMS_OUTPUT.PUT_LINE(q'~      o.window = w ? { name: w.name, start: w.start, end: w.end, secs: (w.end - w.start) / 1000, open: w.open } : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  // Recurring failures: the same object failing with the same error across runs~');
DBMS_OUTPUT.PUT_LINE(q'~  const FAILS = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  function addFail(con, target, error, o, when) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const err = (error || 'Oracle recorded no error text for this failure').replace(/\s+/g, ' ').slice(0, 300);~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    const k = con + '|' + target + '|' + err;~');
DBMS_OUTPUT.PUT_LINE(q'~    let f = FAILS.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!f) FAILS.set(k, f = { con: con, target: target, error: err, runs: new Set(), first: when, last: when, lastOp: o });~');
DBMS_OUTPUT.PUT_LINE(q'~    f.runs.add(o.key);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (when < f.first) f.first = when;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (when >= f.last) { f.last = when; f.lastOp = o; }~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  TASKS.forEach((t) => { if (t.status === 'FAILED' && t.op) addFail(t.con, showTarget(t.target), t.error || t.op.error, t.op, t.start || t.op.start); });~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'gather' && o.status === 'FAILED' && !o.stats.failed) addFail(o.con, showTarget(o.target), o.error, o, o.start);~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const FAILLIST = [...FAILS.values()].sort((a, b) => b.runs.size - a.runs.size || b.last - a.last);~');
DBMS_OUTPUT.PUT_LINE(q'~  // Failures Oracle documents as expected; they do not make a run incomplete~');
DBMS_OUTPUT.PUT_LINE(q'~  const BENIGN = [~');
DBMS_OUTPUT.PUT_LINE(q'~    { re: /X\$LOGMNR_CONTENTS.*log ?miner or data guard must be started/i, why: 'X$LOGMNR_CONTENTS can only be analyzed while LogMiner runs; the automatic job tries it every time. Harmless.' }~');
DBMS_OUTPUT.PUT_LINE(q'~  ];~');
DBMS_OUTPUT.PUT_LINE(q'~  const benign = (err) => BENIGN.find((b) => b.re.test(err || '')) || null;~');
DBMS_OUTPUT.PUT_LINE(q'~  FAILLIST.forEach((f) => { f.benign = benign(f.target + ' ' + f.error); f.om = isOM(f.con, f.target.split('.')[0]); });~');
DBMS_OUTPUT.PUT_LINE(q'~  const chronic = new Set(FAILLIST.filter((f) => f.runs.size >= 3).map((f) => f.con + '|' + f.target));~');
DBMS_OUTPUT.PUT_LINE(q'~  function verdict(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const s = o.stats;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'FAILED') return { sev: 'crit', label: 'Failed', why: o.error || 'The operation failed.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'TIMED OUT') return { sev: 'crit', label: 'Timed out', why: 'Stopped before finishing (end of the maintenance window or AUTO_TASK_MAX_RUN_TIME).' + (s.notDone ? ' ' + fmtN(s.notDone) + ' objects not processed.' : '') };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.abandoned) return { sev: 'crit', label: 'Never finished', why: 'Still IN PROGRESS a day later: the session ended (killed, instance restart) before the operation could record its end.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status === 'IN PROGRESS') return { sev: 'info', label: 'Running', why: 'In progress when the report was generated.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh && /STOPPED|FAILED|BROKEN/.test(o.ajh.status)) return { sev: 'crit', label: 'Job ' + o.ajh.status.toLowerCase(), why: o.ajh.info || 'The scheduler reports the job as ' + o.ajh.status + '.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.notDone) return { sev: 'crit', label: fmtN(s.notDone) + ' not processed', why: fmtN(s.notDone) + ' objects were queued but never completed (status pending, skipped or timed out).' };~');
DBMS_OUTPUT.PUT_LINE(q'~    const fails = o.tasks.filter((t) => t.status === 'FAILED');~');
DBMS_OUTPUT.PUT_LINE(q'~    const exp = fails.filter((t) => benign(t.name + ' ' + t.error));~');
DBMS_OUTPUT.PUT_LINE(q'~    const expected = exp.length;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.failed && expected === s.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      return { sev: 'good', label: 'Complete', why: 'Every object it picked was gathered, except ' + plural(expected, 'expected failure') + ' (' + exp.map((t) => t.name).join(', ') + ').', expected: expected };~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const real = fails.filter((t) => exp.indexOf(t) < 0);~');
DBMS_OUTPUT.PUT_LINE(q'~      const allChronic = fails.length === s.failed && real.every((t) => chronic.has(t.con + '|' + showTarget(t.target)));~');
DBMS_OUTPUT.PUT_LINE(q'~      return { sev: 'warn', label: fmtN(s.failed - expected) + ' failed', expected: expected,~');
DBMS_OUTPUT.PUT_LINE(q'~        why: fmtN(s.failed - expected) + ' of ' + fmtN(s.n) + ' objects failed' + (allChronic ? ' (the same objects fail in every run)' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~          (expected ? ', plus ' + plural(expected, 'expected failure') : '') + '.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.status && o.status !== 'COMPLETED') return { sev: 'warn', label: titleCase(o.status), why: 'Status ' + o.status + '.' };~');
DBMS_OUTPUT.PUT_LINE(q'~    return { sev: 'good', label: 'Complete', why: o.kind === 'other' ? 'Completed.' : 'Every object it picked was gathered.' };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => { o.v = verdict(o); });~');
DBMS_OUTPUT.PUT_LINE(q'~  // Batches: the calls one job or session made back to back (gaps under two~');
DBMS_OUTPUT.PUT_LINE(q'~  // minutes).  The runs list shows a batch as one row that opens up.~');
DBMS_OUTPUT.PUT_LINE(q'~  const BATCHES = [];~');
DBMS_OUTPUT.PUT_LINE(q'~  (() => {~');
DBMS_OUTPUT.PUT_LINE(q'~    const cur = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    OPS.filter((o) => o.kind !== 'auto').sort((a, b) => a.start - b.start).forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = o.con + '|' + (o.job || 'sid ' + o.sid);~');
DBMS_OUTPUT.PUT_LINE(q'~      let b = cur.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!b || o.start - b.end > 120e3) {~');
DBMS_OUTPUT.PUT_LINE(q'~        b = { id: BATCHES.length, con: o.con, job: o.job, sid: o.sid, ops: [], start: o.start, end: o.endEff };~');
DBMS_OUTPUT.PUT_LINE(q'~        cur.set(k, b);~');
DBMS_OUTPUT.PUT_LINE(q'~        BATCHES.push(b);~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      b.ops.push(o);~');
DBMS_OUTPUT.PUT_LINE(q'~      b.end = Math.max(b.end, o.endEff);~');
DBMS_OUTPUT.PUT_LINE(q'~      o.batch = b;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~  })();~');
DBMS_OUTPUT.PUT_LINE(q'~  const AUTO = OPS.filter((o) => o.kind === 'auto');~');
DBMS_OUTPUT.PUT_LINE(q'~  const GATHERS = OPS.filter((o) => o.kind === 'gather');~');
DBMS_OUTPUT.PUT_LINE(q'~  const lastAuto = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  AUTO.forEach((o) => { const l = lastAuto.get(o.con); if (!l || o.start > l.start) lastAuto.set(o.con, o); });~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------- derived: still needing stats~');
DBMS_OUTPUT.PUT_LINE(q'~  const lastAttempt = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~  TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!t.start) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    const k = conKey(t.con, t.name);~');
DBMS_OUTPUT.PUT_LINE(q'~    const l = lastAttempt.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!l || t.start > l.start) lastAttempt.set(k, t);~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  OPS.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind !== 'gather' || !/table_stats$/.test(o.op)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    const k = conKey(o.con, showTarget(o.target) + (o.params.partname && splitTarget(o.target).length < 3 ? '.' + o.params.partname : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~    const l = lastAttempt.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!l || o.start > l.start) lastAttempt.set(k, { start: o.start, status: o.status, error: o.error, op: o });~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const CATS = {~');
DBMS_OUTPUT.PUT_LINE(q'~    failed: { sev: 'crit', title: 'Last gather failed', text: 'The last gather of it in the period failed. Stale until the error is fixed.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missed: { sev: 'crit', title: 'Missed by the last automatic run', text: 'Its changes were recorded before the last automatic run started, yet that run did not gather it (run stopped early, object outside AUTOSTATS_TARGET, or a table preference).' },~');
DBMS_OUTPUT.PUT_LINE(q'~    locked: { sev: 'warn', title: 'Stale or missing, but locked', text: 'Locked: the automatic job and every gather without FORCE skip it. Check the lock is intentional.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missing: { sev: 'warn', title: 'No statistics at all', text: 'Never gathered: the optimizer uses dynamic sampling. The automatic job takes these first; check why it has not.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    fresh: { sev: 'info', title: 'Stale since the last automatic run', text: 'Changed after the last automatic run started. The next run should take it.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    stale: { sev: 'info', title: 'Stale, time of change unknown', text: 'Marked stale but no DML monitoring row tells when it changed (e.g. no automatic run in the period to compare with).' },~');
DBMS_OUTPUT.PUT_LINE(q'~    missingSub: { sev: 'info', title: 'Subpartitions without statistics', text: 'Usually by design: GRANULARITY AUTO does not gather subpartition statistics for every subpartitioning type.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    fixed: { sev: 'info', title: 'Fixed objects (X$) without statistics', text: 'Gathered only by GATHER_FIXED_OBJECTS_STATS or GATHER_DICTIONARY_STATS; some X$ tables can never be analyzed.' }~');
DBMS_OUTPUT.PUT_LINE(q'~  };~');
DBMS_OUTPUT.PUT_LINE(q'~  const CAT_ORDER = ['failed', 'missed', 'locked', 'missing', 'fresh', 'stale', 'missingSub', 'fixed'];~');
DBMS_OUTPUT.PUT_LINE(q'~  const BL = rows('bl').map((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    const b = {~');
DBMS_OUTPUT.PUT_LINE(q'~      con: r[0], owner: r[1], table: r[2], part: r[3], sub: r[4], type: r[5] || '',~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: r[6], blocks: r[7], analyzed: ts(r[8]), stale: r[9] === 'YES', locked: r[10],~');
DBMS_OUTPUT.PUT_LINE(q'~      ins: r[11], upd: r[12], del: r[13], trunc: r[14] === 'YES', dmlTs: ts(r[15]), om: r[16] === 'Y'~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    b.name = [b.owner, b.table, b.part, b.sub].filter(Boolean).join('.');~');
DBMS_OUTPUT.PUT_LINE(q'~    b.missing = !b.analyzed;~');
DBMS_OUTPUT.PUT_LINE(q'~    const la = lastAuto.get(b.con);~');
DBMS_OUTPUT.PUT_LINE(q'~    const att = lastAttempt.get(conKey(b.con, b.name)) ||~');
DBMS_OUTPUT.PUT_LINE(q'~      (b.sub ? lastAttempt.get(conKey(b.con, [b.owner, b.table, b.sub].join('.'))) : null);~');
DBMS_OUTPUT.PUT_LINE(q'~    b.attempt = att || null;~');
DBMS_OUTPUT.PUT_LINE(q'~    b.prefs = TPREFMAP.get(conKey(b.con, b.owner + '.' + b.table)) || [];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (att && att.status === 'FAILED') b.cat = 'failed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.locked) b.cat = 'locked';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.type === 'FIXED TABLE') b.cat = 'fixed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.missing && b.type === 'SUBPARTITION') b.cat = 'missingSub';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.missing) b.cat = 'missing';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.dmlTs && la && b.dmlTs < la.start) b.cat = 'missed';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (b.dmlTs && la) b.cat = 'fresh';~');
DBMS_OUTPUT.PUT_LINE(q'~    else b.cat = 'stale';~');
DBMS_OUTPUT.PUT_LINE(q'~    b.dml = (b.ins || 0) + (b.upd || 0) + (b.del || 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    b.pct = b.rows ? (100 * b.dml) / b.rows : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    return b;~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  const BLAGG = rows('blagg').map((r) => ({ con: r[0], om: r[1] === 'Y', type: r[2], stale: r[3] === 'Y', missing: r[4] === 'Y', locked: r[5] === 'Y', n: r[6] }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const blTruncated = BL.length >= (META.maxBacklog || 5000);~');
DBMS_OUTPUT.PUT_LINE(q'~  // Column statistics below the table level (sql/60_columns.sql)~');
DBMS_OUTPUT.PUT_LINE(q'~  const COLCATS = {~');
DBMS_OUTPUT.PUT_LINE(q'~    nostats: { sev: 'warn', title: 'Column without statistics', text: 'The table has statistics but this column has none, typically because it was added after the last gather. The optimizer guesses its selectivity.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    older: { sev: 'warn', title: 'Older than the table statistics', text: 'Over an hour older than the table statistics: the last gather left this column out (a METHOD_OPT naming only some columns, or FOR TABLE). Its distinct values, nulls and histogram describe older data.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    legacyhb: { sev: 'warn', title: 'Height-balanced histogram', text: 'Only built with a fixed ESTIMATE_PERCENT. With AUTO_SAMPLE_SIZE, 19c builds frequency, top-frequency or hybrid histograms instead, which estimate popular values much better.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    small: { sev: 'info', title: 'Histogram with few buckets', text: 'Fewer than half the buckets it could have (254, or one per distinct value): METHOD_OPT asked for a small SIZE. Values between two endpoints get an average estimate.' },~');
DBMS_OUTPUT.PUT_LINE(q'~    freqgap: { sev: 'info', title: 'Frequency histogram missing values', text: 'Fewer buckets than distinct values: some values were not in the sample, or long strings that start alike share one endpoint. Values missing from it get a guessed estimate.' }~');
DBMS_OUTPUT.PUT_LINE(q'~  };~');
DBMS_OUTPUT.PUT_LINE(q'~  const COLCAT_ORDER = ['nostats', 'older', 'legacyhb', 'small', 'freqgap'];~');
DBMS_OUTPUT.PUT_LINE(q'~  const COLCAT_SHORT = { nostats: 'without statistics', older: 'older than their table', legacyhb: 'with a height-balanced histogram', small: 'with a small histogram', freqgap: 'with gaps in a frequency histogram' };~');
DBMS_OUTPUT.PUT_LINE(q'~  const COLS = rows('cols').map((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    const c = {~');
DBMS_OUTPUT.PUT_LINE(q'~      con: r[0], owner: r[1], table: r[2], col: r[3], dtype: r[4], cat: r[5], hist: r[6], ndv: r[7], buckets: r[8],~');
DBMS_OUTPUT.PUT_LINE(q'~      nulls: r[9], sample: r[10], analyzed: ts(r[11]), tabAnalyzed: ts(r[12]), rows: r[13], om: r[14] === 'Y'~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    c.name = c.owner + '.' + c.table;~');
DBMS_OUTPUT.PUT_LINE(q'~    c.full = c.name + '.' + c.col;~');
DBMS_OUTPUT.PUT_LINE(q'~    c.prefs = TPREFMAP.get(conKey(c.con, c.name)) || [];~');
DBMS_OUTPUT.PUT_LINE(q'~    return c;~');
DBMS_OUTPUT.PUT_LINE(q'~  }).filter((c) => COLCATS[c.cat]);~');
DBMS_OUTPUT.PUT_LINE(q'~  const COLAGG = rows('colagg').map((r) => ({ con: r[0], om: r[1] === 'Y', cat: r[2], n: r[3], tables: r[4] }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const colTruncated = COLS.length >= (META.maxBacklog || 5000);~');
DBMS_OUTPUT.PUT_LINE(q'~  // DML monitoring: what the flushed counters cover, and what is about to go stale~');
DBMS_OUTPUT.PUT_LINE(q'~  const MON = rows('mon').map((r) => ({ con: r[0], n: r[1], newest: ts(r[2]), level: r[3] }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const NEAR = rows('near').map((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~    const b = {~');
DBMS_OUTPUT.PUT_LINE(q'~      con: r[0], owner: r[1], table: r[2], part: r[3], sub: r[4], type: r[5] || '', rows: r[6], analyzed: ts(r[7]),~');
DBMS_OUTPUT.PUT_LINE(q'~      ins: r[8] || 0, upd: r[9] || 0, del: r[10] || 0, dmlTs: ts(r[11]), th: r[12], om: r[13] === 'Y'~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    b.name = [b.owner, b.table, b.part, b.sub].filter(Boolean).join('.');~');
DBMS_OUTPUT.PUT_LINE(q'~    b.dml = b.ins + b.upd + b.del;~');
DBMS_OUTPUT.PUT_LINE(q'~    b.pct = b.rows ? (100 * b.dml) / b.rows : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    b.share = b.pct != null && b.th ? b.pct / b.th : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    return b;~');
DBMS_OUTPUT.PUT_LINE(q'~  });~');
DBMS_OUTPUT.PUT_LINE(q'~  // D.tabs: the tables the Table view knows about (sql/70_tables.sql)~');
DBMS_OUTPUT.PUT_LINE(q'~  const TABS = rows('tabs').map((r) => ({~');
DBMS_OUTPUT.PUT_LINE(q'~    con: r[0], owner: r[1], table: r[2], ptype: r[3], subptype: r[4], nparts: r[5], interval: r[6] === 'Y',~');
DBMS_OUTPUT.PUT_LINE(q'~    rows: r[7], blocks: r[8], analyzed: ts(r[9]), stale: r[10] === 'YES', locked: r[11], om: r[12] === 'Y',~');
DBMS_OUTPUT.PUT_LINE(q'~    pStale: r[13] || 0, pMissing: r[14] || 0, pNewest: ts(r[15]), pOldest: ts(r[16]), name: r[1] + '.' + r[2]~');
DBMS_OUTPUT.PUT_LINE(q'~  }));~');
DBMS_OUTPUT.PUT_LINE(q'~  const TABMAP = new Map(TABS.map((t) => [conKey(t.con, t.name), t]));~');
DBMS_OUTPUT.PUT_LINE(q'~  // D.syn: partitions with an incremental-statistics synopsis, per table~');
DBMS_OUTPUT.PUT_LINE(q'~  const SYN = new Map(rows('syn').map((r) => [conKey(r[0], r[1] + '.' + r[2]), { parts: r[3], newest: ts(r[4]), oldest: ts(r[5]) }]));~');
DBMS_OUTPUT.PUT_LINE(q'~  const tabHref = (con, name) => '#table/' + con + '/' + encodeURIComponent(name);~');
DBMS_OUTPUT.PUT_LINE(q'~  // "OWNER.TABLE" as a link into the Table view (the name as is when unknown)~');
DBMS_OUTPUT.PUT_LINE(q'~  function tabLink(con, name, label) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return name ? '<a class="tl" href="' + tabHref(con, name) + '">' + esc(label || name) + '</a>' : esc(label || '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // An object's name with its partition set apart: OWNER.TABLE <pill>partition P1</pill>.~');
DBMS_OUTPUT.PUT_LINE(q'~  // With link, the name opens the Table view when the table is known.~');
DBMS_OUTPUT.PUT_LINE(q'~  function pieceName(t, link) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const base = t.piece ? t.parts.slice(0, -1).join('.') : t.name;~');
DBMS_OUTPUT.PUT_LINE(q'~    const name = '<code>' + (link && t.tab ? tabLink(t.con, t.tab, base) : esc(base)) + '</code>';~');
DBMS_OUTPUT.PUT_LINE(q'~    return !t.piece ? name : name + ' <span class="pill">' + (/SUB/.test(t.type) ? 'subpartition ' : 'partition ') + esc(t.piece) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Backlog and near-stale rows: the table as a link, the partition as a pill;~');
DBMS_OUTPUT.PUT_LINE(q'~  // a group's pill lists its partitions on hover~');
DBMS_OUTPUT.PUT_LINE(q'~  function objCell(b, withCon) {~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = '<code>' + tabLink(b.con, b.owner + '.' + b.table) + '</code>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (b.group) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const names = b.members.map((x) => [x.part, x.sub].filter(Boolean).join('.'));~');
DBMS_OUTPUT.PUT_LINE(q'~      h += ' <span class="pill" data-tip="' + esc(names.slice(0, 15).map(esc).join('<br>') + (names.length > 15 ? '<br>+' + fmtN(names.length - 15) + ' more' : '')) + '">' + esc(plural(b.members.length, b.type.toLowerCase())) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (b.part || b.sub) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += ' <span class="pill">' + (b.sub ? 'subpartition ' : 'partition ') + esc([b.part, b.sub].filter(Boolean).join('.')) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (b.type && b.type !== 'TABLE') {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += ' <span class="pill">' + esc(b.type.toLowerCase()) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    return h + (withCon ? ' <span class="pill">' + esc(conName(b.con)) + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Keep the tail (the partition) when a long name must be cut~');
DBMS_OUTPUT.PUT_LINE(q'~  function shortName(name, max) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (name.length <= max) return name;~');
DBMS_OUTPUT.PUT_LINE(q'~    const tail = name.slice(-Math.min(18, Math.floor(max / 2)));~');
DBMS_OUTPUT.PUT_LINE(q'~    return name.slice(0, max - tail.length - 1) + '\u2026' + tail;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function sevBadge(sev, label, tip) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<span class="sev ' + sev + '"' + (tip ? ' data-tip="' + esc(tip) + '"' : '') + '><i>' + SEV_ICON[sev] + '</i>' + esc(label) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const kindLabel = { auto: 'Automatic job', gather: 'Manual / custom gather', other: 'Other DBMS_STATS call' };~');
DBMS_OUTPUT.PUT_LINE(q'~  function opLabel(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto') return o.highFreq ? 'Automatic job (high-frequency)' : 'Automatic job';~');
DBMS_OUTPUT.PUT_LINE(q'~    return o.op;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function opTarget(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto') return 'database (AUTO)';~');
DBMS_OUTPUT.PUT_LINE(q'~    const parts = splitTarget(o.target);~');
DBMS_OUTPUT.PUT_LINE(q'~    return parts.join('.') + (o.params.partname && parts.length < 3 ? '.' + o.params.partname : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function opTip(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<b>' + esc(opLabel(o)) + (o.kind === 'auto' ? '' : ' ' + esc(opTarget(o))) + '</b>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(conName(o.con)) + ', ' + esc(fmtT(o.start, true)) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(fmtDur(o.secs)) + (o.stats.n ? ', ' + plural(o.stats.n, 'object') : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(o.v.label) + (o.v.sev !== 'good' ? '<br><span class="muted">' + esc(o.v.why) + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ---------------------------------------------------------------- tables~');
DBMS_OUTPUT.PUT_LINE(q'~  // spec: { cols: [{ key, label, num, cls, html(r), val(r), tip }], rows, sort: [key, dir], limit, href(r), empty,~');
DBMS_OUTPUT.PUT_LINE(q'~  //         kids(r) -> rows shown under r when it is opened, rowKey(r), onSort([key, dir]) }~');
DBMS_OUTPUT.PUT_LINE(q'~  function renderTable(host, spec) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const st = host._t || (host._t = { sort: spec.sort || null, limit: spec.limit || 300 });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!st.open) st.open = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    const cols = spec.cols;~');
DBMS_OUTPUT.PUT_LINE(q'~    let data = spec.rows.slice();~');
DBMS_OUTPUT.PUT_LINE(q'~    const cmp = (() => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!st.sort) return null;~');
DBMS_OUTPUT.PUT_LINE(q'~      const c = cols.find((c) => c.key === st.sort[0]);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!c) return null;~');
DBMS_OUTPUT.PUT_LINE(q'~      const val = c.val || ((r) => r[c.key]);~');
DBMS_OUTPUT.PUT_LINE(q'~      const dir = st.sort[1];~');
DBMS_OUTPUT.PUT_LINE(q'~      return (a, b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const x = val(a), y = val(b);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (x == null && y == null) return 0;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (x == null) return 1;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (y == null) return -1;~');
DBMS_OUTPUT.PUT_LINE(q'~        return (x < y ? -1 : x > y ? 1 : 0) * dir;~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~    })();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cmp) data.sort(cmp);~');
DBMS_OUTPUT.PUT_LINE(q'~    const shown = data.slice(0, st.limit);~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = '<div class="tablewrap"><table><thead><tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    cols.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const sorted = st.sort && st.sort[0] === c.key;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<th data-sort="' + c.key + '" class="' + (c.num ? 'num ' : '') + (sorted ? 'sorted' + (st.sort[1] > 0 ? ' asc' : '') : '') + '"' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (c.tip ? ' data-tip="' + esc(c.tip) + '"' : '') + '>' + esc(c.label) + '</th>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '</tr></thead><tbody>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!shown.length) h += '<tr><td colspan="' + cols.length + '" class="note">' + esc(spec.empty || 'Nothing to show.') + '</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const row = (r, kid) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const kids = !kid && spec.kids ? spec.kids(r) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      const key = kids ? String(spec.rowKey(r)) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      const open = kids && st.open.has(key);~');
DBMS_OUTPUT.PUT_LINE(q'~      const href = kids ? null : spec.href ? spec.href(r) : null;~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~      let t = '<tr class="' + (kid ? 'kid ' : '') + (kids ? 'group click' + (open ? ' open' : '') : href ? 'click' : '') + '"' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (href ? ' data-href="' + esc(href) + '"' : '') + (kids ? ' data-toggle="' + esc(key) + '"' : '') + '>';~');
DBMS_OUTPUT.PUT_LINE(q'~      cols.forEach((c, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const v = c.html ? c.html(r) : esc(r[c.key]);~');
DBMS_OUTPUT.PUT_LINE(q'~        const disc = i ? '' : kids ? '<button type="button" class="disc" aria-expanded="' + !!open + '" aria-label="' + (open ? 'Close' : 'Open') + ' this group"></button>' : spec.kids ? '<span class="disc-pad"></span>' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~        t += '<td class="' + (c.num ? 'num ' : '') + (c.cls || '') + '">' + disc + (v == null ? '' : v) + '</td>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      t += '</tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~      if (open) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const ks = cmp ? kids.slice().sort(cmp) : kids;~');
DBMS_OUTPUT.PUT_LINE(q'~        ks.slice(0, 500).forEach((k) => { t += row(k, true); });~');
DBMS_OUTPUT.PUT_LINE(q'~        if (ks.length > 500) t += '<tr class="kid"><td colspan="' + cols.length + '" class="note">First 500 of ' + fmtN(ks.length) + '.</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      return t;~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    shown.forEach((r) => { h += row(r, false); });~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (data.length > shown.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="more-rows note">Showing ' + fmtN(shown.length) + ' of ' + fmtN(data.length) + ' rows. <button type="button">Show 500 more</button></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (data.length > 20) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="more-rows note">' + fmtN(data.length) + ' rows.</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    host.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    host.querySelectorAll('th[data-sort]').forEach((th) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      th.onclick = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const k = th.getAttribute('data-sort');~');
DBMS_OUTPUT.PUT_LINE(q'~        const c = cols.find((c) => c.key === k);~');
DBMS_OUTPUT.PUT_LINE(q'~        st.sort = st.sort && st.sort[0] === k ? [k, -st.sort[1]] : [k, c && (c.num || c.desc) ? -1 : 1];~');
DBMS_OUTPUT.PUT_LINE(q'~        if (spec.onSort) spec.onSort(st.sort); else renderTable(host, spec);~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    host.querySelectorAll('tr[data-toggle]').forEach((tr) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      tr.onclick = (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        if (e.target.closest('a,[data-copy]')) return;~');
DBMS_OUTPUT.PUT_LINE(q'~        const k = tr.getAttribute('data-toggle');~');
DBMS_OUTPUT.PUT_LINE(q'~        if (st.open.has(k)) st.open.delete(k); else st.open.add(k);~');
DBMS_OUTPUT.PUT_LINE(q'~        renderTable(host, spec);~');
DBMS_OUTPUT.PUT_LINE(q'~        const again = host.querySelector('tr[data-toggle="' + (window.CSS && CSS.escape ? CSS.escape(k) : k) + '"] .disc');~');
DBMS_OUTPUT.PUT_LINE(q'~        if (again) again.focus({ preventScroll: true });~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const more = host.querySelector('.more-rows button');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (more) more.onclick = () => { st.limit += 500; renderTable(host, spec); };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Sort order in the address: "start" ascending, "-start" descending~');
DBMS_OUTPUT.PUT_LINE(q'~  const sortParam = (sort) => (sort ? (sort[1] < 0 ? '-' : '') + sort[0] : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  const parseSort = (p, dflt) => (p ? (p[0] === '-' ? [p.slice(1), -1] : [p, 1]) : dflt);~');
DBMS_OUTPUT.PUT_LINE(q'~  // Copy to the clipboard; plain http (no secure context) falls back to execCommand~');
DBMS_OUTPUT.PUT_LINE(q'~  function copyText(text) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (navigator.clipboard && window.isSecureContext) return navigator.clipboard.writeText(text);~');
DBMS_OUTPUT.PUT_LINE(q'~    const ta = document.createElement('textarea');~');
DBMS_OUTPUT.PUT_LINE(q'~    ta.value = text;~');
DBMS_OUTPUT.PUT_LINE(q'~    ta.setAttribute('readonly', '');~');
DBMS_OUTPUT.PUT_LINE(q'~    ta.style.position = 'fixed';~');
DBMS_OUTPUT.PUT_LINE(q'~    ta.style.opacity = '0';~');
DBMS_OUTPUT.PUT_LINE(q'~    (document.querySelector('dialog[open]') || document.body).appendChild(ta);~');
DBMS_OUTPUT.PUT_LINE(q'~    ta.select();~');
DBMS_OUTPUT.PUT_LINE(q'~    try { document.execCommand('copy'); } finally { ta.remove(); }~');
DBMS_OUTPUT.PUT_LINE(q'~    return Promise.resolve();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ---------------------------------------------------------------- charts~');
DBMS_OUTPUT.PUT_LINE(q'~  const PLOT_L = 52;~');
DBMS_OUTPUT.PUT_LINE(q'~  const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];~');
DBMS_OUTPUT.PUT_LINE(q'~  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];~');
DBMS_OUTPUT.PUT_LINE(q'~  function niceMax(v) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!(v > 0)) return 1;~');
DBMS_OUTPUT.PUT_LINE(q'~    const p = Math.pow(10, Math.floor(Math.log10(v)));~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = v / p;~');
DBMS_OUTPUT.PUT_LINE(q'~    return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * p;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function timeTicks(a, b, width, minPx) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const span = b - a;~');
DBMS_OUTPUT.PUT_LINE(q'~    const steps = [1e3, 5e3, 15e3, 30e3, 60e3, 5 * 60e3, 15 * 60e3, 30 * 60e3, 3600e3, 2 * 3600e3, 3 * 3600e3, 6 * 3600e3, 12 * 3600e3, DAY];~');
DBMS_OUTPUT.PUT_LINE(q'~    const step = steps.find((s) => (s / span) * width >= minPx) || DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~    const off = tzOff(a) * 60000;~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let t = Math.ceil((a + off) / step) * step - off; t <= b; t += step) out.push(t);~');
DBMS_OUTPUT.PUT_LINE(q'~    return { ticks: out, step: step };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Day columns shared by the overview charts, in the selected time zone~');
DBMS_OUTPUT.PUT_LINE(q'~  function dayAxis(width) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const d0 = dayStart(T0), d1 = dayStart(GEN) + DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~    const nd = Math.max(1, Math.round((d1 - d0) / DAY));~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(240, width - PLOT_L - 8);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cw = W / nd;~');
DBMS_OUTPUT.PUT_LINE(q'~    const col = (t) => Math.round((dayStart(t) - d0) / DAY);~');
DBMS_OUTPUT.PUT_LINE(q'~    const tod = (t) => (t - dayStart(t)) / DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~    const x = (t) => PLOT_L + (col(t) + tod(t)) * cw;~');
DBMS_OUTPUT.PUT_LINE(q'~    return { d0: d0, d1: d1, nd: nd, W: W, cw: cw, col: col, tod: tod, x: x };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function dayLabels(ax, y) {~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '';~');
DBMS_OUTPUT.PUT_LINE(q'~    const every = Math.max(1, Math.ceil(26 / ax.cw));~');
DBMS_OUTPUT.PUT_LINE(q'~    let lastMonth = -1;~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i += every) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const ds = ax.d0 + i * DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~      const d = new Date(ds + tzOff(ds + 3600e3) * 60000 + 3600e3);~');
DBMS_OUTPUT.PUT_LINE(q'~      const m = d.getUTCMonth();~');
DBMS_OUTPUT.PUT_LINE(q'~      const lbl = m !== lastMonth ? MONTHS[m] + ' ' + d.getUTCDate() : String(d.getUTCDate());~');
DBMS_OUTPUT.PUT_LINE(q'~      lastMonth = m;~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (PLOT_L + (i + 0.5) * ax.cw) + '" y="' + y + '" text-anchor="' + (i === 0 ? 'start' : 'middle') + '" dx="' + (i === 0 ? -ax.cw / 2 + 2 : 0) + '">' + lbl + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    return s;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function isWeekend(ds) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const d = new Date(ds + tzOff(ds + 3600e3) * 60000 + 3600e3).getUTCDay();~');
DBMS_OUTPUT.PUT_LINE(q'~    return d === 0 || d === 6;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function dayKey(ms) { return fmtT(ms).slice(0, 10); }~');
DBMS_OUTPUT.PUT_LINE(q'~  // The overview's signature chart: days across, hours of the day down.~');
DBMS_OUTPUT.PUT_LINE(q'~  // Maintenance windows are the night bands; each automatic run is a bar~');
DBMS_OUTPUT.PUT_LINE(q'~  // at its start time (height = duration), each other gather a dot.~');
DBMS_OUTPUT.PUT_LINE(q'~  function nightSVG(width, con) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const ax = dayAxis(width);~');
DBMS_OUTPUT.PUT_LINE(q'~    const top = 4, H = 192, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const y = (f) => top + f * H;~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + (top + H + bottom) + '" role="img" aria-label="When statistics were gathered in ' + esc(conName(con)) + ', by day and time of day">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<defs><pattern id="hatch-' + con + '" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line class="hatch" x1="0" y1="0" x2="0" y2="6"/></pattern></defs>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const conWins = WINS.filter((w) => w.con === con && w.maint && w.end > ax.d0 && w.start < GEN);~');
DBMS_OUTPUT.PUT_LINE(q'~    const conAuto = AUTO.filter((o) => o.con === con);~');
DBMS_OUTPUT.PUT_LINE(q'~    // a closed window in which no automatic run started~');
DBMS_OUTPUT.PUT_LINE(q'~    conWins.forEach((w) => { w.empty = !w.open && w.end < GEN && !conAuto.some((o) => o.start >= w.start - 60e3 && o.start <= w.end); });~');
DBMS_OUTPUT.PUT_LINE(q'~    const today = ax.col(GEN);~');
DBMS_OUTPUT.PUT_LINE(q'~    const noWin = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i++) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const ds = ax.d0 + i * DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (isWeekend(ds)) s += '<rect class="weekend" x="' + (PLOT_L + i * ax.cw) + '" y="' + top + '" width="' + ax.cw + '" height="' + H + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      // no maintenance window touched this day and no automatic run: database down or windows off~');
DBMS_OUTPUT.PUT_LINE(q'~      noWin[i] = i < today && !conWins.some((w) => w.start < ds + DAY && w.end > ds) && !conAuto.some((o) => o.start >= ds && o.start < ds + DAY);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (noWin[i]) s += '<rect class="nowin" fill="url(#hatch-' + con + ')" x="' + (PLOT_L + i * ax.cw + 1) + '" y="' + top + '" width="' + Math.max(1, ax.cw - 2) + '" height="' + H + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    [0, 6, 12, 18, 24].forEach((h) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line class="' + (h % 24 ? 'grid' : 'axis') + '" x1="' + PLOT_L + '" x2="' + (PLOT_L + ax.W) + '" y1="' + y(h / 24) + '" y2="' + y(h / 24) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (PLOT_L - 8) + '" y="' + (y(h / 24) + 4) + '" text-anchor="end">' + String(h).padStart(2, '0') + ':00</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    // clickable day columns (open the runs of that day), with a summary of the day~');
DBMS_OUTPUT.PUT_LINE(q'~    const days = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i++) days.push({ auto: 0, bad: 0, man: 0, wins: [] });~');
DBMS_OUTPUT.PUT_LINE(q'~    OPS.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (o.con !== con || o.kind === 'other' || o.start < ax.d0 || (o.om && !showOM)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const dd = days[ax.col(o.start)];~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!dd) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (o.kind === 'auto') { dd.auto++; if (o.v.sev !== 'good') dd.bad++; } else dd.man++;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    WINS.forEach((w) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (w.con !== con || !w.maint || w.start < ax.d0) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const dd = days[ax.col(w.start)];~');
DBMS_OUTPUT.PUT_LINE(q'~      if (dd) dd.wins.push(w);~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i++) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const ds = ax.d0 + i * DAY;~');
DBMS_OUTPUT.PUT_LINE(q'~      const dd = days[i];~');
DBMS_OUTPUT.PUT_LINE(q'~      const d = new Date(ds + tzOff(ds + 3600e3) * 60000 + 3600e3);~');
DBMS_OUTPUT.PUT_LINE(q'~      const tip = '<b>' + WEEKDAYS[d.getUTCDay()] + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCDate() + '</b>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<br>' + (dd.auto ? plural(dd.auto, 'automatic run') + (dd.bad ? ', ' + fmtN(dd.bad) + ' with problems' : '') : 'No automatic run') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (dd.man ? '<br>' + plural(dd.man, 'manual or custom gather') : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        dd.wins.map((w) => '<br>' + esc(w.name) + ' opened ' + esc(fmtClock(w.start)) + ' for ' + esc(fmtDur((w.end - w.start) / 1000)) + (w.empty ? ', no automatic run in it' : '')).join('') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (noWin[i] ? '<br>No maintenance window opened: database down, or the windows disabled' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<br><span class="muted">Click to list this day</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<rect class="day" x="' + (PLOT_L + i * ax.cw) + '" y="' + top + '" width="' + ax.cw + '" height="' + H + '" data-tip="' + esc(tip) + '" data-href="#runs?day=' + dayKey(ds + 3600e3) + (CONS.size > 1 ? '&con=' + con : '') + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    conWins.forEach((w) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      let a = Math.max(w.start, ax.d0);~');
DBMS_OUTPUT.PUT_LINE(q'~      const e = Math.min(w.end, GEN);~');
DBMS_OUTPUT.PUT_LINE(q'~      let guard = 0;~');
DBMS_OUTPUT.PUT_LINE(q'~      while (a < e && guard++ < 60) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const ds = dayStart(a);~');
DBMS_OUTPUT.PUT_LINE(q'~        const segEnd = Math.min(e, ds + DAY);~');
DBMS_OUTPUT.PUT_LINE(q'~        const x0 = PLOT_L + ax.col(a) * ax.cw + 1;~');
DBMS_OUTPUT.PUT_LINE(q'~        const y0 = y(ax.tod(a)), y1 = segEnd === ds + DAY ? y(1) : y(ax.tod(segEnd));~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="win' + (w.empty ? ' empty' : '') + '" pointer-events="none" x="' + (x0 + 0.5) + '" y="' + (y0 + 0.5) + '" width="' + Math.max(1, ax.cw - 3) + '" height="' + Math.max(1, y1 - y0 - 1) + '" rx="2"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~        if (a === w.start) s += '<rect class="win-edge' + (w.empty ? ' empty' : '') + '" pointer-events="none" x="' + x0 + '" y="' + y0 + '" width="' + Math.max(1, ax.cw - 2) + '" height="2"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~        a = segEnd;~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const bw = Math.max(4, ax.cw * 0.62);~');
DBMS_OUTPUT.PUT_LINE(q'~    OPS.filter((o) => o.con === con && o.kind === 'gather' && o.start >= ax.d0 && (showOM || !o.om)).forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cx = PLOT_L + (ax.col(o.start) + 0.8) * ax.cw;~');
DBMS_OUTPUT.PUT_LINE(q'~      const r = o.v.sev === 'crit' ? 3.2 : Math.min(2.6, Math.max(1.6, ax.cw * 0.09));~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<circle class="dot ' + (o.v.sev === 'crit' ? 'f-crit' : 'f-man') + '" cx="' + cx + '" cy="' + y(ax.tod(o.start)) + '" r="' + r + '" data-href="#run/' + o.key + '" data-tip="' + esc(opTip(o)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    conAuto.filter((o) => o.start >= ax.d0).sort((a, b) => SEV_RANK[a.v.sev] - SEV_RANK[b.v.sev]).forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const x0 = PLOT_L + (ax.col(o.start) + 0.06) * ax.cw;~');
DBMS_OUTPUT.PUT_LINE(q'~      // short runs still get a mark big enough to see and to click~');
DBMS_OUTPUT.PUT_LINE(q'~      const h = Math.max(7, (o.secs / 86400) * H);~');
DBMS_OUTPUT.PUT_LINE(q'~      const y0 = Math.min(y(ax.tod(o.start)), y(1) - h);~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<rect class="mark f-' + o.v.sev + '" x="' + x0 + '" y="' + y0 + '" width="' + bw + '" height="' + h + '" rx="1.5" data-href="#run/' + o.key + '" data-tip="' + esc(opTip(o)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const nx = PLOT_L + ax.col(GEN) * ax.cw;~');
DBMS_OUTPUT.PUT_LINE(q'~    s += '<line class="now" x1="' + nx + '" x2="' + (nx + ax.cw) + '" y1="' + y(ax.tod(GEN)) + '" y2="' + y(ax.tod(GEN)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    s += dayLabels(ax, top + H + 16);~');
DBMS_OUTPUT.PUT_LINE(q'~    return s + '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // One column per automatic run on the same day axis as the night chart~');
DBMS_OUTPUT.PUT_LINE(q'~  function runColumnsSVG(width, runs, val, fmt, label, trend) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const ax = dayAxis(width);~');
DBMS_OUTPUT.PUT_LINE(q'~    const top = 8, H = 132, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const max = niceMax(Math.max(0, ...runs.map(val)));~');
DBMS_OUTPUT.PUT_LINE(q'~    const y = (v) => top + (H - top - bottom) * (1 - v / max);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(AUTO.map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="' + esc(label) + '">';~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i++) {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (isWeekend(ax.d0 + i * DAY)) s += '<rect class="weekend" x="' + (PLOT_L + i * ax.cw) + '" y="' + top + '" width="' + ax.cw + '" height="' + (H - top - bottom) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    [0, max / 2, max].forEach((v) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line class="' + (v ? 'grid' : 'axis') + '" x1="' + PLOT_L + '" x2="' + (PLOT_L + ax.W) + '" y1="' + y(v) + '" y2="' + y(v) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (PLOT_L - 8) + '" y="' + (y(v) + 4) + '" text-anchor="end">' + esc(v ? fmt(v) : '0') + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    let tr = '';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (trend) {~');
DBMS_OUTPUT.PUT_LINE(q'~      cons.forEach((c, k) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const rs = runs.filter((o) => o.con === c);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (rs.length < 4) return;~');
DBMS_OUTPUT.PUT_LINE(q'~        const pts = rs.map((o, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~          const win = rs.slice(Math.max(0, i - 6), i + 1).map(val).sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~          return ax.x(o.start).toFixed(1) + ',' + y(win[Math.floor(win.length / 2)]).toFixed(1);~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~        tr += '<polyline class="trend t-s' + (k % 3 + 1) + '" pointer-events="none" points="' + pts.join(' ') + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const v = val(o);~');
DBMS_OUTPUT.PUT_LINE(q'~      const cx = ax.x(o.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const yy = y(v);~');
DBMS_OUTPUT.PUT_LINE(q'~      const ci = cons.indexOf(o.con) % 3 + 1;~');
DBMS_OUTPUT.PUT_LINE(q'~      const w = Math.max(3, Math.min(8, ax.cw * 0.22));~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<rect class="hit" x="' + (cx - 5) + '" y="' + top + '" width="10" height="' + (H - top - bottom) + '" data-href="#run/' + o.key + '" data-tip="' + esc(opTip(o)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      if (v > 0) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const r = Math.min(2, w / 2, y(0) - yy);~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<path class="mark f-s' + ci + '" pointer-events="none" d="M' + (cx - w / 2) + ',' + y(0) + 'V' + (yy + r) + 'q0,-' + r + ' ' + r + ',-' + r + 'H' + (cx + w / 2 - r) + 'q' + r + ',0 ' + r + ',' + r + 'V' + y(0) + 'Z"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    s += tr + dayLabels(ax, H - 4);~');
DBMS_OUTPUT.PUT_LINE(q'~    return s + '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // One run's objects over time.  Up to 40 objects: one labelled row each.~');
DBMS_OUTPUT.PUT_LINE(q'~  // More: packed lanes, each object in the first lane free at its start, so~');
DBMS_OUTPUT.PUT_LINE(q'~  // serial work shares a lane and concurrent work stacks.~');
DBMS_OUTPUT.PUT_LINE(q'~  const typeClass = (t) => (t.status === 'FAILED' ? 'f-crit' : t.status !== 'COMPLETED' ? 'f-warn'~');
DBMS_OUTPUT.PUT_LINE(q'~    : /INDEX/.test(t.type) ? 'f-s3' : /PARTITION/.test(t.type) ? 'f-s2' : 'f-s1');~');
DBMS_OUTPUT.PUT_LINE(q'~  // Tooltip of one object row: the partition named apart from its table~');
DBMS_OUTPUT.PUT_LINE(q'~  function objTip(t) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const head = t.piece ? '<b>' + esc(t.parts.slice(0, -1).join('.')) + '</b><br>' + esc(t.type.toLowerCase()) + ' <b>' + esc(t.piece) + '</b>'~');
DBMS_OUTPUT.PUT_LINE(q'~      : '<b>' + esc(t.name) + '</b><br>' + esc(t.type.toLowerCase());~');
DBMS_OUTPUT.PUT_LINE(q'~    return head + ', ' + esc(t.status.toLowerCase()) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(fmtClock(t.start, true)) + ', ' + esc(fmtDur(t.secs)) + (t.size != null ? ', size ' + fmtN(t.size) : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      (t.hist.length ? '<br>Histograms: ' + esc(t.hist.join(', ')) : '') + (t.error ? '<br><span class="muted">' + esc(t.error) + '</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function ganttSVG(width, o, tasks) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const timed = tasks.filter((t) => t.start).sort((a, b) => a.start - b.start || (b.secs || 0) - (a.secs || 0));~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    const rowsMode = timed.length <= 40;~');
DBMS_OUTPUT.PUT_LINE(q'~    const MAXL = 24;~');
DBMS_OUTPUT.PUT_LINE(q'~    const lanes = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const lane = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!rowsMode) {~');
DBMS_OUTPUT.PUT_LINE(q'~      timed.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const end = t.end || t.start;~');
DBMS_OUTPUT.PUT_LINE(q'~        let i = lanes.findIndex((e) => e <= t.start);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (i < 0) i = lanes.length < MAXL ? lanes.push(end) - 1 : lanes.indexOf(Math.min(...lanes));~');
DBMS_OUTPUT.PUT_LINE(q'~        lanes[i] = Math.max(lanes[i] || 0, end);~');
DBMS_OUTPUT.PUT_LINE(q'~        lane.set(t, i);~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const n = rowsMode ? timed.length : lanes.length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const rowH = rowsMode ? 20 : 16;~');
DBMS_OUTPUT.PUT_LINE(q'~    const L = rowsMode ? 290 : 40, R = 8, top = 4, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(200, width - L - R);~');
DBMS_OUTPUT.PUT_LINE(q'~    const from = Math.min(o.start, ...timed.map((t) => t.start));~');
DBMS_OUTPUT.PUT_LINE(q'~    const to = Math.max(o.endEff, ...timed.map((t) => t.end || t.start), from + 1000);~');
DBMS_OUTPUT.PUT_LINE(q'~    const x = (t) => L + ((t - from) / (to - from)) * W;~');
DBMS_OUTPUT.PUT_LINE(q'~    const H = top + n * rowH + bottom;~');
DBMS_OUTPUT.PUT_LINE(q'~    const tt = timeTicks(from, to, W, 90);~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="Objects of this run over time">';~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<line class="grid" x1="' + x(t) + '" x2="' + x(t) + '" y1="' + top + '" y2="' + (H - bottom) + '"/>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!rowsMode) for (let i = 0; i < n; i++) s += '<text x="' + (L - 10) + '" y="' + (top + i * rowH + 12) + '" text-anchor="end">' + (i + 1) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.window && o.window.end > from && o.window.end <= to) s += '<line class="end-line" x1="' + x(o.window.end) + '" x2="' + x(o.window.end) + '" y1="' + top + '" y2="' + (H - bottom) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    timed.forEach((t, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const y = top + (rowsMode ? i : lane.get(t)) * rowH;~');
DBMS_OUTPUT.PUT_LINE(q'~      const a = x(t.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const w = Math.max(1, x(t.end || t.start) - a - (rowsMode ? 0 : 1));~');
DBMS_OUTPUT.PUT_LINE(q'~      const tip = objTip(t);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (rowsMode) {~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<text x="0" y="' + (y + 14) + '" style="fill:var(--ink-2)">' + esc(shortName(t.name, 42)) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="hit" x="0" y="' + y + '" width="' + (L + W) + '" height="' + rowH + '" data-tip="' + esc(tip) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + typeClass(t) + '" pointer-events="none" x="' + a + '" y="' + (y + 4) + '" width="' + Math.max(2, w) + '" height="' + (rowH - 8) + '" rx="2"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      } else {~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + typeClass(t) + '" x="' + a + '" y="' + (y + 2) + '" width="' + Math.max(1.5, w) + '" height="' + (rowH - 4) + '" data-tip="' + esc(tip) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    tt.ticks.forEach((t) => { s += '<text x="' + x(t) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(fmtClock(t, tt.step < 60e3)) + '</text>'; });~');
DBMS_OUTPUT.PUT_LINE(q'~    return { svg: s + '</svg>', capped: lanes.length >= MAXL };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ chrome~');
DBMS_OUTPUT.PUT_LINE(q'~  const ICON_THEME = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3a9 9 0 1 0 9 9 7 7 0 0 1-9-9z"/></svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  const app = document.getElementById('app');~');
DBMS_OUTPUT.PUT_LINE(q'~  function scopeText() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const container = META.cdb !== 'YES' ? 'Whole database' :~');
DBMS_OUTPUT.PUT_LINE(q'~      META.conId === 1 ? 'All containers' : 'Pluggable database ' + META.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    return container + (META.scopeSchema ? ', ' + META.scopeSchema + (META.scopeTable ? '.' + META.scopeTable : '') : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function chrome() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const dbo = dbOffsetMin();~');
DBMS_OUTPUT.PUT_LINE(q'~    app.innerHTML =~');
DBMS_OUTPUT.PUT_LINE(q'~      '<header class="top"><div class="ident"><span class="db">' + esc(META.db || '?') + '</span>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="scope">' + esc(scopeText()) + ', last ' + DAYS + ' days</span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<nav class="tabs" aria-label="Views"><a href="#overview" data-v="overview">Overview</a><a href="#runs" data-v="runs">Runs</a>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<a href="#backlog" data-v="backlog">Needs statistics</a><a href="#columns" data-v="columns">Columns</a><a href="#table" data-v="table">Table</a><a href="#config" data-v="config">Setup</a></nav>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="prefs"><label data-tip="Include gathers, failures and stale objects in Oracle-maintained schemas (SYS, SYSTEM, AUDSYS, ...). Automatic runs always show."><input type="checkbox" id="om"> Oracle schemas</label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<label>Times <select id="tz">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<option value="db">DB host (' + offLabel(dbo) + ')</option><option value="utc">UTC</option><option value="local">This browser (' + offLabel(-new Date().getTimezoneOffset()) + ')</option>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '</select></label><button type="button" class="icon-btn" id="theme" aria-label="Switch between light and dark">' + ICON_THEME + '</button></div></header>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<main id="view"></main>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<footer class="foot"><span>Generated ' + esc(fmtT(GEN)) + ' (' + esc(tzMode === 'utc' ? 'UTC' : offLabel(tzOff(GEN))) + ')</span><span>' + esc(META.db || '') + ' ' + esc(META.version || '') + ' on ' + esc(META.host || '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '</span><span>Collected as ' + esc(META.user || '') + ' in ' + esc(META.con || '') + '</span><span>Read-only; nothing was changed in the database</span></footer>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<dialog class="drawer" id="drawer" aria-labelledby="drawer-title"></dialog><div id="tip" role="tooltip" popover="manual"></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const tz = document.getElementById('tz');~');
DBMS_OUTPUT.PUT_LINE(q'~    tz.value = tzMode;~');
DBMS_OUTPUT.PUT_LINE(q'~    tz.onchange = () => { tzMode = tz.value; if (store) store.setItem('gd.tz', tzMode); chrome(); wireDrawer(); renderedBase = null; keepScroll = true; route(); };~');
DBMS_OUTPUT.PUT_LINE(q'~    const om = document.getElementById('om');~');
DBMS_OUTPUT.PUT_LINE(q'~    om.checked = showOM;~');
DBMS_OUTPUT.PUT_LINE(q'~    om.onchange = () => setShowOM(om.checked);~');
DBMS_OUTPUT.PUT_LINE(q'~    const savedTheme = store && store.getItem('gd.theme');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (savedTheme) document.documentElement.setAttribute('data-theme', savedTheme);~');
DBMS_OUTPUT.PUT_LINE(q'~    document.getElementById('theme').onclick = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cur = document.documentElement.getAttribute('data-theme') ||~');
DBMS_OUTPUT.PUT_LINE(q'~        (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');~');
DBMS_OUTPUT.PUT_LINE(q'~      const next = cur === 'dark' ? 'light' : 'dark';~');
DBMS_OUTPUT.PUT_LINE(q'~      document.documentElement.setAttribute('data-theme', next);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (store) store.setItem('gd.theme', next);~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function setShowOM(on) {~');
DBMS_OUTPUT.PUT_LINE(q'~    showOM = on;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (store) store.setItem('gd.om', on ? '1' : '0');~');
DBMS_OUTPUT.PUT_LINE(q'~    const box = document.getElementById('om');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (box) box.checked = on;~');
DBMS_OUTPUT.PUT_LINE(q'~    renderedBase = null;~');
DBMS_OUTPUT.PUT_LINE(q'~    keepScroll = true;~');
DBMS_OUTPUT.PUT_LINE(q'~    route();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // "+12 in Oracle schemas": a hint with a one-click way to show them~');
DBMS_OUTPUT.PUT_LINE(q'~  function omHint(n) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return !showOM && n ? ' <button type="button" class="linkish" data-om-on>+' + fmtN(n) + ' in Oracle schemas</button>' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // The tooltip lives in the top layer (popover) so it shows over the run~');
DBMS_OUTPUT.PUT_LINE(q'~  // drawer, which is a modal dialog.  Older browsers: display toggling.~');
DBMS_OUTPUT.PUT_LINE(q'~  const POP = 'showPopover' in HTMLElement.prototype;~');
DBMS_OUTPUT.PUT_LINE(q'~  function hideTip() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const tip = document.getElementById('tip');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!tip) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (POP) { if (tip.matches(':popover-open')) tip.hidePopover(); } else tip.style.display = 'none';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function wireGlobal() {~');
DBMS_OUTPUT.PUT_LINE(q'~    document.addEventListener('mousemove', (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const tip = document.getElementById('tip');~');
DBMS_OUTPUT.PUT_LINE(q'~      const el = e.target.closest && e.target.closest('[data-tip]');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!el) { hideTip(); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      if (tip._el !== el) { tip.innerHTML = el.getAttribute('data-tip'); tip._el = el; }~');
DBMS_OUTPUT.PUT_LINE(q'~      if (POP) { if (!tip.matches(':popover-open')) tip.showPopover(); } else tip.style.display = 'block';~');
DBMS_OUTPUT.PUT_LINE(q'~      const r = tip.getBoundingClientRect();~');
DBMS_OUTPUT.PUT_LINE(q'~      let left = e.clientX + 14, topY = e.clientY + 16;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (left + r.width > innerWidth - 8) left = e.clientX - r.width - 14;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (topY + r.height > innerHeight - 8) topY = e.clientY - r.height - 14;~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.style.left = Math.max(4, left) + 'px';~');
DBMS_OUTPUT.PUT_LINE(q'~      tip.style.top = Math.max(4, topY) + 'px';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    document.addEventListener('click', (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cp = e.target.closest && e.target.closest('[data-copy]');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (cp) {~');
DBMS_OUTPUT.PUT_LINE(q'~        copyText(cp.getAttribute('data-copy')).then(() => {~');
DBMS_OUTPUT.PUT_LINE(q'~          const was = cp.textContent;~');
DBMS_OUTPUT.PUT_LINE(q'~          cp.textContent = 'Copied';~');
DBMS_OUTPUT.PUT_LINE(q'~          cp.classList.add('done');~');
DBMS_OUTPUT.PUT_LINE(q'~          setTimeout(() => { cp.textContent = was; cp.classList.remove('done'); }, 1400);~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~        return;~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      if (e.target.closest && e.target.closest('[data-om-on]')) { setShowOM(true); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      const el = e.target.closest && e.target.closest('[data-href]');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (el && !e.target.closest('a,button,select,input,label')) location.hash = el.getAttribute('data-href');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    document.addEventListener('keydown', (e) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const typing = e.target.closest && e.target.closest('input,select,textarea');~');
DBMS_OUTPUT.PUT_LINE(q'~      const drawer = document.getElementById('drawer');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (e.key === '/' && !typing) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const box = (drawer.open ? drawer : document.getElementById('view')).querySelector('input[type="search"]');~');
DBMS_OUTPUT.PUT_LINE(q'~        if (box) { e.preventDefault(); box.focus(); }~');
DBMS_OUTPUT.PUT_LINE(q'~      } else if (drawer.open && !typing && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const b = drawer.querySelector(e.key === 'ArrowLeft' ? '#prev' : '#next');~');
DBMS_OUTPUT.PUT_LINE(q'~        if (b && !b.disabled) b.click();~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    let rt;~');
DBMS_OUTPUT.PUT_LINE(q'~    window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(() => { renderedBase = null; keepScroll = true; route(); }, 150); });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function missingBox() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const scope = META.scopeSchema ? '<div class="warnbox"><b>Collection scope:</b> ' + esc(scopeText()) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '. Object counts and task totals include only this target. Operation, job and window durations and CPU describe the whole matching run. ' +~');
DBMS_OUTPUT.PUT_LINE(q'~      'Configuration is container context. Calls without matching tasks or an explicit target are excluded.</div>' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!missing.length) return scope;~');
DBMS_OUTPUT.PUT_LINE(q'~    return scope + '<div class="warnbox"><b>Not collected:</b> ' + missing.map(esc).join(', ') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '. Their SQL failed (missing grant, or an object this release lacks); the error text is in the HTML source next to the dataset name.</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function sec(title, sub, body, end, cls) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<section class="sec' + (cls ? ' ' + cls : '') + '"><header><h2>' + esc(title) + '</h2>' + (sub ? '<p class="sub">' + sub + '</p>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      (end ? '<div class="end">' + end + '</div>' : '') + '</header>' + body + '</section>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function seg(id, options, value) {~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="seg" role="group" id="' + id + '">' + options.map((o) =>~');
DBMS_OUTPUT.PUT_LINE(q'~      '<button type="button" data-val="' + esc(o[0]) + '" aria-pressed="' + (o[0] === value) + '">' + esc(o[1]) + (o[2] != null ? '<span class="n">' + fmtN(o[2]) + '</span>' : '') + '</button>').join('') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function wireSeg(root, id, onPick) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const g = root.querySelector('#' + id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!g) return;~');
DBMS_OUTPUT.PUT_LINE(q'~    g.querySelectorAll('button').forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      b.onclick = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        g.querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));~');
DBMS_OUTPUT.PUT_LINE(q'~        onPick(b.getAttribute('data-val'));~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function consLegend() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(AUTO.map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cons.length < 2) return '';~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<div class="legend">' + cons.map((c, i) => '<span><b class="s' + (i % 3 + 1) + '"></b>' + esc(conName(c)) + '</span>').join('') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ overview~');
DBMS_OUTPUT.PUT_LINE(q'~  function appBacklogCounts() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const cnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~    BL.filter((b) => !b.om).forEach((b) => { cnt[b.cat] = (cnt[b.cat] || 0) + 1; });~');
DBMS_OUTPUT.PUT_LINE(q'~    return cnt;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const andList = (xs) => (xs.length < 3 ? xs.join(' and ') : xs.slice(0, -1).join(', ') + ' and ' + xs[xs.length - 1]);~');
DBMS_OUTPUT.PUT_LINE(q'~  // Containers whose last automatic run is more than two days old~');
DBMS_OUTPUT.PUT_LINE(q'~  function stalledCons() {~');
DBMS_OUTPUT.PUT_LINE(q'~    return [...lastAuto.entries()].filter((e) => GEN - e[1].start > 2 * DAY).map((e) => e[0]).sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function headline() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const bad = AUTO.filter((o) => o.v.sev === 'crit').length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const warn = AUTO.filter((o) => o.v.sev === 'warn').length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const cnt = appBacklogCounts();~');
DBMS_OUTPUT.PUT_LINE(q'~    const missed = (cnt.missed || 0) + (cnt.failed || 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const off = ATC.filter((a) => a.status !== 'ENABLED');~');
DBMS_OUTPUT.PUT_LINE(q'~    const stalled = stalledCons();~');
DBMS_OUTPUT.PUT_LINE(q'~    let sev, text, pre = '';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!AUTO.length) { sev = 'crit'; text = 'No automatic statistics run in the last ' + DAYS + ' days.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (off.length) { sev = 'crit'; text = 'The automatic statistics task is disabled in ' + andList(off.map((a) => conName(a.con))) + '.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (stalled.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const last = Math.max(...stalled.map((c) => lastAuto.get(c).start));~');
DBMS_OUTPUT.PUT_LINE(q'~      const days = Math.floor((GEN - last) / DAY);~');
DBMS_OUTPUT.PUT_LINE(q'~      sev = days >= 7 ? 'crit' : 'warn';~');
DBMS_OUTPUT.PUT_LINE(q'~      text = 'No automatic run in ' + andList(stalled.map(conName)) + ' for ' + plural(days, 'day') + '.';~');
DBMS_OUTPUT.PUT_LINE(q'~      const since = WINS.filter((w) => stalled.includes(w.con) && w.maint && w.start > last).length;~');
DBMS_OUTPUT.PUT_LINE(q'~      pre = (since ? plural(since, 'maintenance window') + ' opened since ' + fmtT(last) + ' without one.'~');
DBMS_OUTPUT.PUT_LINE(q'~        : 'No maintenance window has opened since ' + fmtT(last) + ': the database was down, or the windows are disabled.') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (bad ? ' Before that, ' + fmtN(bad) + ' of ' + plural(AUTO.length, 'run') + ' did not finish their work.'~');
DBMS_OUTPUT.PUT_LINE(q'~          : ' Before that, ' + (warn ? 'all ' + plural(AUTO.length, 'run') + ' finished, ' + fmtN(warn) + ' with objects that failed.' : 'all ' + plural(AUTO.length, 'run') + ' gathered everything they picked.'));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (bad) { sev = 'crit'; text = fmtN(bad) + ' of ' + plural(AUTO.length, 'automatic run') + ' did not finish their work.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (missed) { sev = 'crit'; text = plural(missed, 'application object') + (missed === 1 ? ' is' : ' are') + ' stale although the automatic job already ran.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (warn) { sev = 'warn'; text = 'All ' + plural(AUTO.length, 'automatic run') + ' finished, ' + fmtN(warn) + ' with objects that failed.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    else { sev = 'good'; text = 'All ' + plural(AUTO.length, 'automatic run') + ' in ' + DAYS + ' days gathered everything they picked.'; }~');
DBMS_OUTPUT.PUT_LINE(q'~    const appStale = BLAGG.filter((b) => !b.om && b.type !== 'FIXED TABLE' && b.stale).reduce((a, b) => a + b.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    let sub;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (missing.includes('bl')) sub = 'What still needs statistics was not collected.';~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (!appStale && !cnt.missing) sub = 'No application table or partition needs statistics right now.';~');
DBMS_OUTPUT.PUT_LINE(q'~    else sub = plural(appStale, 'application table or partition', 'application tables and partitions') + (appStale === 1 ? ' is' : ' are') + ' stale right now' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (cnt.fresh ? '; ' + fmtN(cnt.fresh) + ' changed after the last automatic run and ' + (cnt.fresh === 1 ? 'is' : 'are') + ' next in line' : '') + '.';~');
DBMS_OUTPUT.PUT_LINE(q'~    return { sev: sev, text: text, sub: (pre ? pre + ' ' : '') + sub };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function findings() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const add = (sev, html, more) => f.push({ sev: sev, html: html, more: more });~');
DBMS_OUTPUT.PUT_LINE(q'~    ATC.forEach((a) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (a.status !== 'ENABLED') add('crit', 'The automatic statistics task is <b>' + esc(a.status.toLowerCase()) + '</b> in ' + esc(conName(a.con)) + '.', 'Nothing gathers stale statistics there unless a custom job does.');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (PREFS.get('AUTOSTATS_TARGET') === 'ORACLE') add('crit', 'AUTOSTATS_TARGET is <b>ORACLE</b> in ' + esc(META.con) + ': the automatic job gathers only Oracle-owned schemas.', 'Application schemas need their own gather jobs.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(ATC.map((a) => a.con).concat(AUTO.map((o) => o.con)))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    cons.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const runs = AUTO.filter((o) => o.con === c);~');
DBMS_OUTPUT.PUT_LINE(q'~      const la = lastAuto.get(c);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!runs.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~        add('crit', 'No automatic statistics run in ' + esc(conName(c)) + ' in the last ' + DAYS + ' days.', 'See Setup: task status and maintenance windows.');~');
DBMS_OUTPUT.PUT_LINE(q'~        return;~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      const bad = runs.filter((o) => o.v.sev === 'crit');~');
DBMS_OUTPUT.PUT_LINE(q'~      const warn = runs.filter((o) => o.v.sev === 'warn');~');
DBMS_OUTPUT.PUT_LINE(q'~      const durs = runs.map((o) => o.secs).sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~      const med = durs[Math.floor(durs.length / 2)];~');
DBMS_OUTPUT.PUT_LINE(q'~      add(bad.length ? 'crit' : warn.length ? 'warn' : 'good', esc(conName(c)) + ': <a href="#runs?kind=auto&con=' + c + '">' + plural(runs.length, 'automatic run') + '</a>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (bad.length ? ', <a href="#runs?kind=auto&con=' + c + '&sev=crit">' + fmtN(bad.length) + ' did not finish</a>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (warn.length ? ', <a href="#runs?kind=auto&con=' + c + '&sev=warn">' + fmtN(warn.length) + ' with failed objects</a>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (!bad.length && !warn.length ? ', all complete' : '') + '.',~');
DBMS_OUTPUT.PUT_LINE(q'~        'Typical run ' + fmtDur(med) + ', longest ' + fmtDur(durs[durs.length - 1]) + '. Last run ' + fmtT(la.start) + ', ' + fmtAgo(la.start) + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (GEN - la.start > 2 * DAY) add('warn', 'The last automatic run in ' + esc(conName(c)) + ' started ' + esc(fmtAgo(la.start)) + '.', 'It normally runs in every maintenance window.');~');
DBMS_OUTPUT.PUT_LINE(q'~      const wins = WINS.filter((w) => w.con === c && w.maint && !w.open && w.start >= T0 && w.end > w.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const empty = wins.filter((w) => !runs.some((o) => o.start >= w.start - 60e3 && o.start <= w.end));~');
DBMS_OUTPUT.PUT_LINE(q'~      if (empty.length) add('warn', esc(conName(c)) + ': ' + plural(empty.length, 'maintenance window') + ' of ' + fmtN(wins.length) + ' passed without an automatic run.', 'Last: ' + esc(empty[empty.length - 1].name) + ' at ' + fmtT(empty[empty.length - 1].start) + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~      const atEnd = runs.filter((o) => o.window && o.end && o.window.end - o.end < 120e3 && o.window.end > o.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (atEnd.length) add('crit', esc(conName(c)) + ': ' + plural(atEnd.length, 'run') + ' ended at the close of the maintenance window.', 'The window is too short for the work.');~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const rec = FAILLIST.filter((x) => x.runs.size >= 2 && !x.benign && (showOM || !x.om));~');
DBMS_OUTPUT.PUT_LINE(q'~    if (rec.length) add('warn', '<a href="#overview/failures">' + plural(rec.length, 'object') + ' failed in more than one run</a>, for example <code>' + esc(rec[0].target) + '</code> in ' + plural(rec[0].runs.size, 'run') + '.', esc(rec[0].error));~');
DBMS_OUTPUT.PUT_LINE(q'~    const cnt = appBacklogCounts();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cnt.missed || cnt.failed) {~');
DBMS_OUTPUT.PUT_LINE(q'~      add('crit', '<a href="#backlog?cat=' + (cnt.missed ? 'missed' : 'failed') + '">' + (cnt.missed ? plural(cnt.missed, 'application object') + ' missed by the last automatic run' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (cnt.missed && cnt.failed ? ', ' : '') + (cnt.failed ? plural(cnt.failed, 'object') + ' whose last gather failed' : '') + '</a>.', 'Stale now, after the job ran.');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const basic = MON.filter((m) => /^BASIC$/i.test(m.level || ''));~');
DBMS_OUTPUT.PUT_LINE(q'~    if (basic.length) add('crit', 'STATISTICS_LEVEL is <b>BASIC</b> in ' + esc(META.con) + ': DML monitoring is off.', 'Nothing is counted in DBA_TAB_MODIFICATIONS, so no table ever turns stale and the automatic job regathers nothing.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const colCnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~    COLAGG.filter((a) => showOM || !a.om).forEach((a) => { colCnt[a.cat] = (colCnt[a.cat] || 0) + a.n; });~');
DBMS_OUTPUT.PUT_LINE(q'~    const colCats = COLCAT_ORDER.filter((c) => colCnt[c]);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (colCats.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const n = colCats.reduce((a, c) => a + colCnt[c], 0);~');
DBMS_OUTPUT.PUT_LINE(q'~      add(colCats.some((c) => COLCATS[c].sev === 'warn') ? 'warn' : 'info',~');
DBMS_OUTPUT.PUT_LINE(q'~        '<a href="#columns">' + plural(n, 'column') + (showOM ? '' : ' in application schemas') + '</a> with doubtful statistics: ' +~');
DBMS_OUTPUT.PUT_LINE(q'~        colCats.map((c) => '<a href="#columns?cat=' + c + '">' + fmtN(colCnt[c]) + ' ' + COLCAT_SHORT[c] + '</a>').join(', ') + '.',~');
DBMS_OUTPUT.PUT_LINE(q'~        'Table statistics fine, column statistics not.');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const near = NEAR.filter((b) => showOM || !b.om);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (near.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      add('info', '<a href="#backlog">' + plural(near.length, 'table or partition', 'tables and partitions') + '</a> ' + (near.length === 1 ? 'is' : 'are') + ' at least halfway to stale' + (showOM ? '' : ' in application schemas') + '.',~');
DBMS_OUTPUT.PUT_LINE(q'~        'From the flushed DML counters only.' + (near.length >= 2000 ? ' The report holds the first 2,000.' : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const gs = GATHERS.filter((o) => showOM || !o.om);~');
DBMS_OUTPUT.PUT_LINE(q'~    const mf = gs.filter((o) => o.v.sev === 'crit');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (gs.length) add(mf.length ? 'warn' : 'good', '<a href="#runs?kind=gather">' + plural(gs.length, 'manual or custom gather') + '</a>' + (showOM ? '' : ' in application schemas') + (mf.length ? ', <a href="#runs?kind=gather&sev=crit">' + fmtN(mf.length) + ' failed</a>' : ', none failed') + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const ben = FAILLIST.filter((x) => x.benign);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (ben.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const names = [...new Set(ben.map((x) => x.target))];~');
DBMS_OUTPUT.PUT_LINE(q'~      add('info', 'Not counted as failures: ' + names.map((n) => '<code>' + esc(n) + '</code>').join(', ') + '.', esc(ben[0].benign.why));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    return f.sort((a, b) => SEV_RANK[b.sev] - SEV_RANK[a.sev]);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  let histMetric = 'secs';~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewOverview(sub) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const hl = headline();~');
DBMS_OUTPUT.PUT_LINE(q'~    const gs = GATHERS.filter((o) => showOM || !o.om);~');
DBMS_OUTPUT.PUT_LINE(q'~    const objs = AUTO.concat(gs).reduce((a, o) => a + o.stats.done, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const hist = AUTO.concat(gs).reduce((a, o) => a + o.stats.hist, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const realFails = FAILLIST.filter((f) => !f.benign && (showOM || !f.om));~');
DBMS_OUTPUT.PUT_LINE(q'~    const failedObjs = new Set(realFails.map((f) => f.con + '|' + f.target)).size;~');
DBMS_OUTPUT.PUT_LINE(q'~    const totalSecs = AUTO.concat(gs).reduce((a, o) => a + o.secs, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cnt = appBacklogCounts();~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = missingBox();~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<section class="hero"><h1 class="verdict"><span class="mark ' + hl.sev + '" aria-hidden="true">' + SEV_ICON[hl.sev] + '</span><span>' + esc(hl.text) + '</span></h1>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<p class="verdict-sub">' + esc(hl.sub) + '</p>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<dl class="stats">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div><dt>Automatic runs</dt><dd><a href="#runs?kind=auto">' + fmtN(AUTO.length) + '</a></dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div><dt>Manual or custom gathers</dt><dd><a href="#runs?kind=gather">' + fmtN(gs.length) + '</a>' + (showOM ? '' : '<small>application schemas</small>') + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div><dt>Objects gathered</dt><dd>' + compact(objs) + '<small>' + compact(hist) + ' with histograms</small></dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div><dt>Objects that failed</dt><dd><a href="#overview/failures">' + fmtN(failedObjs) + '</a></dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div><dt>Time spent gathering</dt><dd>' + esc(fmtDur(totalSecs)) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '</dl></section>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const cons = [...new Set(OPS.filter((o) => o.kind !== 'other').map((o) => o.con).concat(ATC.map((a) => a.con)))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    h += sec('When statistics were gathered', 'One column per day, midnight to midnight. Click a run to open it, an empty spot to list the day.',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="surface">' + cons.map((c) => '<div class="chart night" data-con="' + c + '">' + (cons.length > 1 ? '<div class="chart-head"><h3>' + esc(conName(c)) + '</h3></div>' : '') + '<div class="plot"></div></div>').join('') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="legend"><span><b class="win"></b>Maintenance window</span><span><b class="good"></b>Automatic run, complete</span><span><b class="warn"></b>Some objects failed</span><span><b class="crit"></b>Failed or did not finish</span><span><b class="dot"></b>Manual or custom gather</span><span><b class="weekend"></b>Weekend</span>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span><b class="win-empty"></b>Window without an automatic run</span><span><b class="nowin"></b>No window opened</span></div></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const needRows = CAT_ORDER.filter((c) => cnt[c]);~');
DBMS_OUTPUT.PUT_LINE(q'~    const needMax = Math.max(1, ...needRows.map((c) => cnt[c]));~');
DBMS_OUTPUT.PUT_LINE(q'~    const needs = needRows.length ? '<ul class="needs">' + needRows.map((c) =>~');
DBMS_OUTPUT.PUT_LINE(q'~      '<li><a href="#backlog?cat=' + c + '"><span>' + sevBadge(CATS[c].sev, CATS[c].title) + '</span><span class="n">' + fmtN(cnt[c]) + '</span>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="bar ' + CATS[c].sev + '"><b style="inline-size:' + (100 * cnt[c] / needMax).toFixed(1) + '%"></b></span></a></li>').join('') + '</ul>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<p class="note" style="margin-block-start:0.75rem">Application schemas only. Staleness as of the last DML-monitoring flush.</p>'~');
DBMS_OUTPUT.PUT_LINE(q'~      : '<p class="muted">' + (missing.includes('bl') ? 'Not collected.' : 'Nothing: every application table and partition has fresh statistics.') + '</p>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="split wide-narrow">' + sec('Findings', '', '<ul class="findings">' + findings().map((x) => '<li>' + sevBadge(x.sev, '') + '<div>' + x.html + (x.more ? '<div class="more">' + x.more + '</div>' : '') + '</div></li>').join('') + '</ul>') +~');
DBMS_OUTPUT.PUT_LINE(q'~      sec('Needs statistics now', '', needs) + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += sec('Automatic runs', 'One column per run. Line: median of the last 7.',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="surface"><div class="plot" id="c-hist"></div>' + consLegend() + '</div>',~');
DBMS_OUTPUT.PUT_LINE(q'~      seg('hist-metric', [['secs', 'Run time'], ['objects', 'Objects'], ['failed', 'Failed objects']], histMetric));~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="split">' + sec('Failures', 'Same object and error, counted across runs.', '<div id="t-fail"></div>', '', 'failures') +~');
DBMS_OUTPUT.PUT_LINE(q'~      sec('Slowest objects', 'Gather time over the period.', '<div id="t-heavy"></div>') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    v.querySelectorAll('.chart.night').forEach((el) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const p = el.querySelector('.plot');~');
DBMS_OUTPUT.PUT_LINE(q'~      p.innerHTML = nightSVG(p.clientWidth, Number(el.getAttribute('data-con')));~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const autoSorted = AUTO.slice().sort((a, b) => a.start - b.start);~');
DBMS_OUTPUT.PUT_LINE(q'~    const drawHist = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const p = v.querySelector('#c-hist');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!autoSorted.length) { p.innerHTML = '<p class="muted">No automatic runs in the period.</p>'; return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      const m = { secs: [(o) => o.secs, fmtDur, 'Run time per automatic run'], objects: [(o) => o.stats.n, compact, 'Objects per automatic run'], failed: [(o) => o.stats.failed + o.stats.notDone, compact, 'Failed objects per automatic run'] }[histMetric];~');
DBMS_OUTPUT.PUT_LINE(q'~      p.innerHTML = runColumnsSVG(p.clientWidth, autoSorted, m[0], m[1], m[2], histMetric !== 'failed');~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    drawHist();~');
DBMS_OUTPUT.PUT_LINE(q'~    wireSeg(v, 'hist-metric', (val) => { histMetric = val; drawHist(); });~');
DBMS_OUTPUT.PUT_LINE(q'~    const failHost = v.querySelector('#t-fail');~');
DBMS_OUTPUT.PUT_LINE(q'~    renderTable(failHost, {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: realFails, sort: ['runs', -1], limit: sub === 'failures' ? 1000 : 8, empty: 'No object failed in the period' + (showOM ? '.' : ' in application schemas.'),~');
DBMS_OUTPUT.PUT_LINE(q'~      href: (f) => '#run/' + f.lastOp.key,~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'target', label: 'Object', cls: 'wrap', html: (f) => '<code>' + esc(f.target) + '</code>' + (CONS.size > 1 ? ' <span class="pill">' + esc(conName(f.con)) + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~          '<div class="err sub-err">' + esc(f.error) + '</div>' },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'runs', label: 'Runs', num: true, val: (f) => f.runs.size, html: (f) => fmtN(f.runs.size) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'last', label: 'Last', cls: 't', html: (f) => esc(fmtT(f.last)) }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const ben = FAILLIST.filter((f) => f.benign);~');
DBMS_OUTPUT.PUT_LINE(q'~    const omFails = FAILLIST.filter((f) => !f.benign && f.om).length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const notes = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (ben.length) notes.push('Expected, not counted: ' + [...new Set(ben.map((f) => f.target))].map((t) => '<code>' + esc(t) + '</code>').join(', ') +~');
DBMS_OUTPUT.PUT_LINE(q'~      ' in ' + plural(new Set(ben.flatMap((f) => [...f.runs])).size, 'run') + '.');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (omFails && !showOM) notes.push(omHint(omFails).trim() + ' not shown.');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (notes.length) failHost.insertAdjacentHTML('beforeend', '<p class="note table-note">' + notes.join(' ') + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sub === 'failures') v.querySelector('.failures').scrollIntoView();~');
DBMS_OUTPUT.PUT_LINE(q'~    const heavy = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    const heavyOM = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!t.op || t.op.kind === 'other' || t.secs == null) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!showOM && isOM(t.con, t.parts[0])) { heavyOM.add(t.con + '|' + t.name); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = t.con + '|' + t.name;~');
DBMS_OUTPUT.PUT_LINE(q'~      let x = heavy.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x) heavy.set(k, x = { con: t.con, name: t.name, type: t.type, tab: t.tab, piece: t.piece, parts: t.parts, n: 0, secs: 0, max: 0, last: null });~');
DBMS_OUTPUT.PUT_LINE(q'~      x.n++; x.secs += t.secs; x.max = Math.max(x.max, t.secs);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x.last || t.start > x.last.start) x.last = t;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const hl2 = [...heavy.values()].sort((a, b) => b.secs - a.secs).slice(0, 200);~');
DBMS_OUTPUT.PUT_LINE(q'~    const hmax = hl2.length ? hl2[0].secs : 1;~');
DBMS_OUTPUT.PUT_LINE(q'~    renderTable(v.querySelector('#t-heavy'), {~');
DBMS_OUTPUT.PUT_LINE(q'~      rows: hl2, sort: ['secs', -1], limit: 8, empty: 'No per-object timings recorded.',~');
DBMS_OUTPUT.PUT_LINE(q'~      href: (x) => '#run/' + x.last.op.key,~');
DBMS_OUTPUT.PUT_LINE(q'~      cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'name', label: 'Object', cls: 'wrap', html: (x) => pieceName(x, true) + (x.piece ? '' : ' <span class="pill">' + esc(x.type.toLowerCase()) + '</span>') + (CONS.size > 1 ? ' <span class="pill">' + esc(conName(x.con)) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'n', label: 'Gathers', num: true, html: (x) => fmtN(x.n) },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'secs', label: 'Total', num: true, html: (x) => '<span class="durbar">' + esc(fmtDur(x.secs)) + '<span><b style="inline-size:' + (100 * x.secs / hmax).toFixed(1) + '%"></b></span></span>' }~');
DBMS_OUTPUT.PUT_LINE(q'~      ]~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (heavyOM.size && !showOM) v.querySelector('#t-heavy').insertAdjacentHTML('beforeend', '<p class="note table-note">Application schemas only.' + omHint(heavyOM.size) + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ runs~');
DBMS_OUTPUT.PUT_LINE(q'~  // A batch with at least two matching calls becomes one row that opens up~');
DBMS_OUTPUT.PUT_LINE(q'~  function batchRow(b, members) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const worst = members.reduce((w, o) => (SEV_RANK[o.v.sev] > SEV_RANK[w.v.sev] ? o : w), members[0]);~');
DBMS_OUTPUT.PUT_LINE(q'~    const bad = members.filter((o) => o.v.sev !== 'good').length;~');
DBMS_OUTPUT.PUT_LINE(q'~    const ops = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    members.forEach((o) => ops.set(o.op, (ops.get(o.op) || 0) + 1));~');
DBMS_OUTPUT.PUT_LINE(q'~    const owners = [...new Set(members.map((o) => o.owner).filter(Boolean))];~');
DBMS_OUTPUT.PUT_LINE(q'~    const targets = new Set(members.map((o) => opTarget(o))).size;~');
DBMS_OUTPUT.PUT_LINE(q'~    const st = { n: 0, failed: 0, notDone: 0 };~');
DBMS_OUTPUT.PUT_LINE(q'~    members.forEach((o) => { st.n += o.stats.n; st.failed += o.stats.failed - (o.v.expected || 0); st.notDone += o.stats.notDone; });~');
DBMS_OUTPUT.PUT_LINE(q'~    return {~');
DBMS_OUTPUT.PUT_LINE(q'~      batch: b, members: members, con: b.con, job: b.job, sid: b.sid, kind: members[0].kind,~');
DBMS_OUTPUT.PUT_LINE(q'~      start: members[0].start, end: Math.max(...members.map((o) => o.endEff)),~');
DBMS_OUTPUT.PUT_LINE(q'~      secs: (Math.max(...members.map((o) => o.endEff)) - members[0].start) / 1000,~');
DBMS_OUTPUT.PUT_LINE(q'~      v: bad ? { sev: worst.v.sev, label: fmtN(bad) + ' with problems', why: fmtN(bad) + ' of ' + plural(members.length, 'call') + ' with problems. Worst: ' + worst.v.label + '. ' + worst.v.why } : { sev: 'good', label: 'Complete', why: 'Every call in this batch completed.' },~');
DBMS_OUTPUT.PUT_LINE(q'~      ops: [...ops.entries()].sort((x, y) => y[1] - x[1]), owners: owners, targets: targets, stats: st,~');
DBMS_OUTPUT.PUT_LINE(q'~      window: members[0].window~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const runsState = { kind: 'gathers', con: '', sev: '', text: '', day: '', group: true };~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewRuns(q) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = runsState;~');
DBMS_OUTPUT.PUT_LINE(q'~    f.kind = q.get('kind') || 'gathers'; f.con = q.get('con') || ''; f.sev = q.get('sev') || ''; f.text = q.get('q') || ''; f.day = q.get('day') || '';~');
DBMS_OUTPUT.PUT_LINE(q'~    f.group = q.get('g') !== '0';~');
DBMS_OUTPUT.PUT_LINE(q'~    const consAll = [...new Set(OPS.map((o) => o.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = missingBox() + sec('Runs', 'Every DBMS_STATS operation in the last ' + DAYS + ' days. Back-to-back calls of one job or session form a group. The text filter also matches the objects a run gathered.',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="filters">' + seg('f-kind', [['gathers', 'All gathers'], ['auto', 'Automatic'], ['gather', 'Manual or custom'], ['all', 'Every DBMS_STATS call']], f.kind) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div id="f-sev-host"></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (consAll.length > 1 ? '<label>Container <select id="f-con"><option value="">All</option>' + consAll.map((c) => '<option value="' + c + '">' + esc(conName(c)) + '</option>').join('') + '</select></label>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<input type="search" id="f-q" placeholder="Filter by operation, object, job or error" aria-label="Filter runs">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      seg('f-group', [['1', 'Grouped'], ['0', 'Every call']], f.group ? '1' : '0') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span id="f-day"></span><span class="count" id="f-n"></span></div><div id="t-runs"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const sel = (id) => v.querySelector(id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#f-con')) sel('#f-con').value = f.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-q').value = f.text;~');
DBMS_OUTPUT.PUT_LINE(q'~    const host = sel('#t-runs');~');
DBMS_OUTPUT.PUT_LINE(q'~    host._t = { sort: parseSort(q.get('s'), ['start', -1]), limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~    function apply() {~');
DBMS_OUTPUT.PUT_LINE(q'~      f.con = sel('#f-con') ? sel('#f-con').value : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      f.text = sel('#f-q').value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~      const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.kind !== 'gathers') params.set('kind', f.kind);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.con) params.set('con', f.con);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.sev) params.set('sev', f.sev);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.text) params.set('q', f.text);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.day) params.set('day', f.day);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!f.group) params.set('g', '0');~');
DBMS_OUTPUT.PUT_LINE(q'~      const sp = sortParam(host._t.sort);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (sp && sp !== '-start') params.set('s', sp);~');
DBMS_OUTPUT.PUT_LINE(q'~      setBaseHash('#runs' + (params.toString() ? '?' + params.toString() : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~      // Text matches the run itself, or the objects it gathered (the ones~');
DBMS_OUTPUT.PUT_LINE(q'~      // embedded in this report: a truncated run may hide a hit)~');
DBMS_OUTPUT.PUT_LINE(q'~      const hits = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~      let partial = 0;~');
DBMS_OUTPUT.PUT_LINE(q'~      const textHit = (o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!f.text) return true;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!o.search) o.search = [o.op, opTarget(o), o.job, o.error, o.status, o.v.label].join(' ').toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~        if (o.search.includes(f.text)) return true;~');
DBMS_OUTPUT.PUT_LINE(q'~        const m = o.tasks.filter((t) => t.nameL.includes(f.text));~');
DBMS_OUTPUT.PUT_LINE(q'~        if (m.length) { hits.set(o, m); return true; }~');
DBMS_OUTPUT.PUT_LINE(q'~        if (o.truncated) partial++;~');
DBMS_OUTPUT.PUT_LINE(q'~        return false;~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      const scoped = OPS.filter((o) =>~');
DBMS_OUTPUT.PUT_LINE(q'~        (f.kind === 'all' || (f.kind === 'gathers' ? o.kind !== 'other' : o.kind === f.kind)) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        (!f.con || String(o.con) === f.con) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        (!f.day || dayKey(o.start) === f.day) &&~');
DBMS_OUTPUT.PUT_LINE(q'~        textHit(o));~');
DBMS_OUTPUT.PUT_LINE(q'~      const base = scoped.filter((o) => showOM || !o.om);~');
DBMS_OUTPUT.PUT_LINE(q'~      const hiddenOM = scoped.length - base.length;~');
DBMS_OUTPUT.PUT_LINE(q'~      const n = { crit: 0, warn: 0, good: 0 };~');
DBMS_OUTPUT.PUT_LINE(q'~      base.forEach((o) => { if (n[o.v.sev] != null) n[o.v.sev]++; });~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#f-sev-host').innerHTML = seg('f-sev', [['', 'Any outcome', base.length], ['crit', 'Failed or unfinished', n.crit], ['warn', 'Some objects failed', n.warn], ['good', 'Complete', n.good]], f.sev);~');
DBMS_OUTPUT.PUT_LINE(q'~      wireSeg(v, 'f-sev', (val) => { f.sev = val; host._t.limit = 300; apply(); });~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#f-day').innerHTML = f.day ? '<button type="button" class="chip-x" id="f-day-x" aria-label="Show all days">' + esc(f.day) + ' <span aria-hidden="true">\u2715</span></button>' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.day) sel('#f-day-x').onclick = () => { f.day = ''; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = base.filter((o) => !f.sev || o.v.sev === f.sev);~');
DBMS_OUTPUT.PUT_LINE(q'~      let rowsOut = list;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.group) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const by = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~        list.forEach((o) => { if (o.batch) { if (!by.has(o.batch)) by.set(o.batch, []); by.get(o.batch).push(o); } });~');
DBMS_OUTPUT.PUT_LINE(q'~        const done = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~        rowsOut = [];~');
DBMS_OUTPUT.PUT_LINE(q'~        list.forEach((o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~          const m = o.batch ? by.get(o.batch) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~          if (!m || m.length < 2) { rowsOut.push(o); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~          if (done.has(o.batch)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~          done.add(o.batch);~');
DBMS_OUTPUT.PUT_LINE(q'~          rowsOut.push(batchRow(o.batch, m.slice().sort((a, b) => a.start - b.start)));~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      const groups = rowsOut.filter((r) => r.members).length;~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#f-n').innerHTML = esc(plural(list.length, 'operation')) + (groups ? ', ' + esc(plural(groups, 'group')) : '') + omHint(hiddenOM) +~');
DBMS_OUTPUT.PUT_LINE(q'~        (partial ? ' <span data-tip="' + esc(plural(partial, 'run embeds', 'runs embed') + ' only the first ' + fmtN(META.maxTasks) + ' objects; a hit there is not found. Raise max_tasks_per_run.') + '">(' + fmtN(partial) + ' searched partially)</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      // the objects that matched the text, under the run's target~');
DBMS_OUTPUT.PUT_LINE(q'~      const hitText = (o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const m = o.members ? o.members.flatMap((x) => hits.get(x) || []) : hits.get(o);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!m || !m.length) return '';~');
DBMS_OUTPUT.PUT_LINE(q'~        const names = [...new Set(m.map((t) => t.name))];~');
DBMS_OUTPUT.PUT_LINE(q'~        return '<div class="hits">' + names.slice(0, 3).map((n) => '<code>' + esc(n) + '</code>').join(', ') + (names.length > 3 ? ' +' + fmtN(names.length - 3) : '') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      const dmax = Math.max(1, ...rowsOut.map((o) => o.secs));~');
DBMS_OUTPUT.PUT_LINE(q'~      const objs = (o) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const fail = o.stats.failed + o.stats.notDone - (o.members ? 0 : o.v.expected || 0);~');
DBMS_OUTPUT.PUT_LINE(q'~        const exp = o.members ? 0 : o.v.expected || 0;~');
DBMS_OUTPUT.PUT_LINE(q'~        return (o.stats.n ? fmtN(o.stats.n) : '') + (fail ? ' <span class="err">(' + fmtN(fail) + ' failed)</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~          (exp ? ' <span class="muted" data-tip="' + esc('Expected failure, not counted: ' + esc(o.v.why)) + '">(' + fmtN(exp) + ' expected)</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: rowsOut, href: (o) => '#run/' + o.key, empty: 'No operation matches these filters.',~');
DBMS_OUTPUT.PUT_LINE(q'~        kids: (r) => r.members || null, rowKey: (r) => r.batch.id,~');
DBMS_OUTPUT.PUT_LINE(q'~        onSort: () => apply(),~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'start', label: 'Started', cls: 't', desc: true, html: (o) => esc(fmtT(o.start, true)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'sev', label: 'Outcome', val: (o) => SEV_RANK[o.v.sev], desc: true, html: (o) => sevBadge(o.v.sev, o.v.label, o.v.why) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'op', label: 'Operation', val: (o) => (o.members ? o.ops[0][0] : opLabel(o)),~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~            html: (o) => '<span class="nw">' + (o.members ? '<b>' + fmtN(o.members.length) + ' calls</b>' : esc(opLabel(o))) + (CONS.size > 1 ? ' <span class="pill">' + esc(conName(o.con)) + '</span>' : '') + '</span>' +~');
DBMS_OUTPUT.PUT_LINE(q'~              (o.members ? ' <span class="muted">' + esc(o.ops.slice(0, 2).map((x) => x[0] + (o.ops.length > 1 ? ' \u00d7' + fmtN(x[1]) : '')).join(', ') + (o.ops.length > 2 ? ', +' + (o.ops.length - 2) + ' more' : '')) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'target', label: 'Target', cls: 'wrap', val: (o) => (o.members ? o.owners.join(',') : opTarget(o)),~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (o) => (o.members ? (o.owners.length ? o.owners.slice(0, 3).map((x) => '<code>' + esc(x) + '</code>').join(', ') + (o.owners.length > 3 ? ' +' + (o.owners.length - 3) : '') : '') + ' <span class="muted">' + esc(plural(o.targets, 'target')) + '</span>'~');
DBMS_OUTPUT.PUT_LINE(q'~              : o.kind === 'auto' ? '<span class="muted">whole database</span>' : '<code>' + (splitTarget(o.target).length >= 2 && /table_stats$/.test(o.op) ? tabLink(o.con, splitTarget(o.target).slice(0, 2).join('.'), opTarget(o)) : esc(opTarget(o))) + '</code>') + hitText(o) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'n', label: 'Objects', num: true, val: (o) => o.stats.n, html: objs },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'secs', label: 'Duration', num: true, tip: 'For a group: from its first call to the end of its last', html: (o) => '<span class="durbar">' + esc(fmtDur(o.secs)) + '<span><b style="inline-size:' + Math.max(2, 100 * o.secs / dmax).toFixed(1) + '%"></b></span></span>' },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'job', label: 'Job and window', cls: 'nw', html: (o) => (o.job ? '<code>' + esc(o.job) + '</code>' : '<span class="muted">session ' + esc(o.sid) + '</span>') + (o.window ? ' <span class="pill">' + esc(o.window.name) + '</span>' : '') }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    wireSeg(v, 'f-kind', (val) => { f.kind = val; host._t.limit = 300; apply(); });~');
DBMS_OUTPUT.PUT_LINE(q'~    wireSeg(v, 'f-group', (val) => { f.group = val === '1'; host._t.limit = 300; apply(); });~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#f-con')) sel('#f-con').onchange = () => { host._t.limit = 300; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~    let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#f-q').oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 180); };~');
DBMS_OUTPUT.PUT_LINE(q'~    apply();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ one run (drawer)~');
DBMS_OUTPUT.PUT_LINE(q'~  function runSiblings(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const same = OPS.filter((x) => x.kind === o.kind && x.con === o.con && (o.kind !== 'gather' || x.op === o.op)).sort((a, b) => a.start - b.start);~');
DBMS_OUTPUT.PUT_LINE(q'~    const i = same.indexOf(o);~');
DBMS_OUTPUT.PUT_LINE(q'~    return { prev: same[i - 1], next: same[i + 1], pos: i + 1, total: same.length };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // The run before this one: same container and kind; a manual gather also needs the same target~');
DBMS_OUTPUT.PUT_LINE(q'~  function previousRun(o) {~');
DBMS_OUTPUT.PUT_LINE(q'~    let best = null;~');
DBMS_OUTPUT.PUT_LINE(q'~    OPS.forEach((x) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (x.kind !== o.kind || x.con !== o.con || x.start >= o.start || x === o) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (o.kind !== 'auto' && (x.op !== o.op || opTarget(x) !== opTarget(o))) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!best || x.start > best.start) best = x;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    return best;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function openRun(con, id) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const d = document.getElementById('drawer');~');
DBMS_OUTPUT.PUT_LINE(q'~    const o = OPMAP.get(con + '/' + id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!o) {~');
DBMS_OUTPUT.PUT_LINE(q'~      d.innerHTML = '<div class="drawer-head"><h2 id="drawer-title">Run not found</h2><div class="nav"><button type="button" id="close">Close</button></div></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div class="drawer-body"><p>No operation ' + esc(id) + ' in container ' + esc(con) + ' in this report.</p></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      d.querySelector('#close').onclick = () => d.close();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!d.open) d.showModal();~');
DBMS_OUTPUT.PUT_LINE(q'~      return;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const s = o.stats;~');
DBMS_OUTPUT.PUT_LINE(q'~    const sib = runSiblings(o);~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = '<div class="drawer-head"><div><h2 id="drawer-title">' + esc(opLabel(o)) + (o.kind === 'auto' ? '' : ' <code>' + esc(opTarget(o)) + '</code>') + '</h2>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="where">' + esc(conName(o.con)) + ', ' + esc(fmtT(o.start, true)) + ', run ' + fmtN(sib.pos) + ' of ' + fmtN(sib.total) + '</div></div>' + sevBadge(o.v.sev, o.v.label) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="nav"><button type="button" id="prev"' + (sib.prev ? '' : ' disabled') + ' aria-label="Previous run">\u2190 Previous</button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<button type="button" id="next"' + (sib.next ? '' : ' disabled') + ' aria-label="Next run">Next \u2192</button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<button type="button" id="close" aria-label="Close" autofocus>Close <kbd>Esc</kbd></button></div></div><div class="drawer-body">';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.v.sev !== 'good') h += '<div class="warnbox">' + esc(o.v.why) + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const prev = previousRun(o);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (prev) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const ps = prev.stats;~');
DBMS_OUTPUT.PUT_LINE(q'~      const delta = (a, b, fmt, bad) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const d = a - b;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (Math.abs(d) < 1e-9 || (fmt === fmtDur && Math.abs(d) < 0.5)) return '<span class="delta same">same</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~        const cls = bad == null ? '' : (d > 0) === bad ? ' worse' : ' better';~');
DBMS_OUTPUT.PUT_LINE(q'~        return '<span class="delta' + cls + '">' + (d > 0 ? '+' : '\u2212') + esc(fmt(Math.abs(d))) + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      const pf = ps.failed - (prev.v.expected || 0) + ps.notDone, of = s.failed - (o.v.expected || 0) + s.notDone;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<section class="compare"><p class="note">Compared with the <a href="#run/' + prev.key + '">previous run</a>, ' + esc(fmtT(prev.start)) + '</p><dl class="stats compact">' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div><dt>Duration</dt><dd>' + esc(fmtDur(o.secs)) + delta(o.secs, prev.secs, fmtDur, null) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div><dt>Objects</dt><dd>' + fmtN(s.n) + delta(s.n, ps.n, fmtN, null) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div><dt>Gathered</dt><dd>' + fmtN(s.done) + delta(s.done, ps.done, fmtN, null) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div><dt>Failed or not processed</dt><dd>' + fmtN(of) + delta(of, pf, fmtN, true) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div><dt>With histograms</dt><dd>' + fmtN(s.hist) + delta(s.hist, ps.hist, fmtN, null) + '</dd></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '</dl></section>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const facts = [~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Started', esc(fmtT(o.start, true))],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Ended', o.end ? esc(fmtT(o.end, true)) : '<span class="muted">no end recorded</span>'],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Duration', esc(fmtDur(o.secs))],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Status', esc(o.status)],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Job', o.job ? '<code>' + esc(o.job) + '</code>' : '<span class="muted">called from a session</span>'],~');
DBMS_OUTPUT.PUT_LINE(q'~      ['Session', esc(o.sid)]~');
DBMS_OUTPUT.PUT_LINE(q'~    ];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.sjr) facts.push(['Scheduler', esc(o.sjr.status.toLowerCase()) + ', ran ' + esc(fmtDur(o.sjr.secs)) + ', CPU ' + esc(fmtDur(o.sjr.cpu)) + (o.sjr.error ? ', ORA-' + esc(o.sjr.error) : '')]);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.window) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const used = o.end && o.window.end > o.window.start ? (100 * (o.end - o.window.start)) / (o.window.end - o.window.start) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      facts.push(['Window', esc(o.window.name) + ', ' + esc(fmtSpan(o.window.start, o.window.end)) + ' (' + esc(fmtDur(o.window.secs)) + ')' +~');
DBMS_OUTPUT.PUT_LINE(q'~        (o.end ? '<br><span class="muted">Finished ' + esc(fmtDur((o.window.end - o.end) / 1000)) + ' before the window closed' + (used != null ? ', ' + used.toFixed(0) + '% of the window had passed' : '') + '</span>' : '')]);~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.ajh && o.ajh.info) facts.push(['Job info', esc(o.ajh.info)]);~');
DBMS_OUTPUT.PUT_LINE(q'~    const kv = '<dl class="kv">' + facts.map((f) => '<dt>' + esc(f[0]) + '</dt><dd>' + f[1] + '</dd>').join('') + '</dl>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const pk = Object.keys(o.params);~');
DBMS_OUTPUT.PUT_LINE(q'~    const params = pk.length ? '<dl class="kv">' + pk.map((k) => '<dt>' + esc(k) + '</dt><dd><code>' + esc(o.params[k] === '' ? "''" : o.params[k]) + '</code></dd>').join('') + '</dl>' : '<p class="muted">No parameters recorded.</p>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="split">' + sec('Run', '', '<div class="surface">' + kv + (o.error ? '<div class="err-block">' + esc(o.error) + '</div>' : '') + '</div>') +~');
DBMS_OUTPUT.PUT_LINE(q'~      sec('Parameters', 'As resolved. DEFAULT_*: the preference in force.', '<div class="surface">' + params + '</div>') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.n) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const types = Object.keys(s.byType).sort((a, b) => s.byType[b].secs - s.byType[a].secs);~');
DBMS_OUTPUT.PUT_LINE(q'~      let tb = '<div class="tablewrap"><table><thead><tr><th>Object type</th><th class="num">Objects</th><th class="num">Gathered</th><th class="num">Failed</th><th class="num">Not processed</th><th class="num">With histograms</th><th class="num">Time</th></tr></thead><tbody>';~');
DBMS_OUTPUT.PUT_LINE(q'~      const row = (label, b, bold) => '<tr><td>' + (bold ? '<b>' + label + '</b>' : label) + '</td><td class="num">' + fmtN(b.n) + '</td><td class="num">' + fmtN(b.done) + '</td><td class="num">' + (b.failed ? '<span class="err">' + fmtN(b.failed) + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~        '</td><td class="num">' + ((b.other || b.notDone) ? '<span class="err">' + fmtN(b.other || b.notDone) + '</span>' : '') + '</td><td class="num">' + (b.hist ? fmtN(b.hist) : '') + '</td><td class="num">' + esc(fmtDur(b.secs)) + '</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~      types.forEach((t) => { tb += row(esc(t.toLowerCase()), s.byType[t]); });~');
DBMS_OUTPUT.PUT_LINE(q'~      if (types.length > 1) tb += row('Total', s, true);~');
DBMS_OUTPUT.PUT_LINE(q'~      tb += '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      const conc = o.params.concurrent === 'TRUE' || (s.secs > o.secs * 1.2 && o.secs > 1);~');
DBMS_OUTPUT.PUT_LINE(q'~      const owners = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~      o.tasks.forEach((t) => { const k = t.parts[0] || '?'; const x = owners.get(k) || { n: 0, secs: 0 }; x.n++; x.secs += t.secs || 0; owners.set(k, x); });~');
DBMS_OUTPUT.PUT_LINE(q'~      const ol = [...owners.entries()].sort((a, b) => b[1].secs - a[1].secs).slice(0, 8);~');
DBMS_OUTPUT.PUT_LINE(q'~      const omax = ol.length ? Math.max(0.001, ol[0][1].secs) : 1;~');
DBMS_OUTPUT.PUT_LINE(q'~      const ot = '<div class="tablewrap"><table><thead><tr><th>Schema</th><th class="num">Objects</th><th class="num">Time</th></tr></thead><tbody>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        ol.map((e) => '<tr><td>' + esc(e[0]) + '</td><td class="num">' + fmtN(e[1].n) + '</td><td class="num"><span class="durbar">' + esc(fmtDur(e[1].secs)) + '<span><b style="inline-size:' + (100 * e[1].secs / omax).toFixed(1) + '%"></b></span></span></td></tr>').join('') + '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      h += '<div class="split wide-narrow">' + sec('What it did', plural(s.n, 'object') + (conc ? '. Objects overlapped, so the times add up to more than the run took.' : '.'), '<div class="surface">' + tb + '</div>') +~');
DBMS_OUTPUT.PUT_LINE(q'~        sec('By schema', o.truncated ? 'From the ' + fmtN(o.tasks.length) + ' objects in this report.' : '', '<div class="surface">' + ot + '</div>') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~      const timedT = o.tasks.filter((t) => t.secs > 0).sort((a, b) => b.secs - a.secs);~');
DBMS_OUTPUT.PUT_LINE(q'~      const tot = timedT.reduce((a, t) => a + t.secs, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (tot > 0 && timedT.length > 1) {~');
DBMS_OUTPUT.PUT_LINE(q'~        const top = timedT.slice(0, 8);~');
DBMS_OUTPUT.PUT_LINE(q'~        const restN = timedT.length - top.length, rest = tot - top.reduce((a, t) => a + t.secs, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~        const segOf = (cls, secs, label, tip) => {~');
DBMS_OUTPUT.PUT_LINE(q'~          const pct = (100 * secs) / tot;~');
DBMS_OUTPUT.PUT_LINE(q'~          return '<span class="' + cls + '" style="flex-grow:' + pct.toFixed(3) + '" data-tip="' + esc(tip) + '">' + (pct >= 6 ? '<em>' + esc(label) + '</em>' : '') + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~        };~');
DBMS_OUTPUT.PUT_LINE(q'~        const strip = top.map((t) => segOf(typeClass(t).replace('f-', 'b-'), t.secs, t.name.split('.').slice(1).join('.') || t.name,~');
DBMS_OUTPUT.PUT_LINE(q'~          objTip(t) + '<br>' + ((100 * t.secs) / tot).toFixed(0) + '% of the object time')).join('') +~');
DBMS_OUTPUT.PUT_LINE(q'~          (restN ? segOf('b-rest', rest, plural(restN, 'other object'), '<b>' + esc(plural(restN, 'other object')) + '</b><br>' + esc(fmtDur(rest)) + ', ' + ((100 * rest) / tot).toFixed(0) + '% of the object time') : '');~');
DBMS_OUTPUT.PUT_LINE(q'~        h += sec('Where the time went', 'Slowest objects, share of all object time (' + esc(fmtDur(tot)) + '). Hover for names.', '<div class="surface"><div class="strip">' + strip + '</div></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~      }~');
DBMS_OUTPUT.PUT_LINE(q'~      h += sec('Objects over time', (o.tasks.length > 40 ? 'Concurrent objects stack into lanes. Hover for the object.' : 'Hover for the object.') +~');
DBMS_OUTPUT.PUT_LINE(q'~        (o.window && o.window.end <= o.endEff + 60e3 ? ' Red line: end of the window.' : ''),~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div class="surface"><div id="gantt"></div><div class="legend"><span><b class="s1"></b>Table</span><span><b class="s2"></b>Partition</span><span><b class="s3"></b>Index</span><span><b class="crit"></b>Failed</span><span><b class="warn"></b>Not completed</span></div></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~      h += sec('Objects', (o.truncated ? fmtN(o.tasks.length) + ' of ' + fmtN(s.n) + ' in this report: failed first, then slowest. Raise max_tasks_per_run to see all. ' : '') + 'Click a name for the table.',~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div class="filters"><div id="o-st-host"></div><label>Type <select id="o-ty"><option value="">Any</option>' + [...new Set(o.tasks.map((t) => t.type))].sort().map((x) => '<option>' + esc(x) + '</option>').join('') + '</select></label>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        '<input type="search" id="o-q" placeholder="Filter objects" aria-label="Filter objects"><span class="count" id="o-n"></span></div><div id="t-obj"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (o.kind !== 'other') {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += sec('What it did', '', '<p>No per-object rows were recorded for this operation' + (o.status === 'COMPLETED' ? '; it found nothing to gather.' : '.') + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (o.kind === 'auto' && lastAuto.get(o.con) === o) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const n = BL.filter((b) => b.con === o.con && !b.om && (b.cat === 'missed' || b.cat === 'failed')).length;~');
DBMS_OUTPUT.PUT_LINE(q'~      h += sec('After this run', 'This is the latest automatic run in ' + esc(conName(o.con)) + '.',~');
DBMS_OUTPUT.PUT_LINE(q'~        '<p>' + (n ? '<a href="#backlog?cat=missed&con=' + o.con + '">' + plural(n, 'application object') + '</a> were stale before this run started and still are, or failed.' : 'Every application object that was stale when this run started has been gathered.') + '</p>');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    d.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~    d.querySelector('#close').onclick = () => d.close();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sib.prev) d.querySelector('#prev').onclick = () => { location.hash = '#run/' + sib.prev.key; };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sib.next) d.querySelector('#next').onclick = () => { location.hash = '#run/' + sib.next.key; };~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!d.open) d.showModal();~');
DBMS_OUTPUT.PUT_LINE(q'~    d.scrollTop = 0;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (s.n && o.tasks.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const g = d.querySelector('#gantt');~');
DBMS_OUTPUT.PUT_LINE(q'~      const gr = ganttSVG(g.clientWidth, o, o.tasks);~');
DBMS_OUTPUT.PUT_LINE(q'~      g.innerHTML = gr.svg + (gr.capped ? '<p class="note">More than 24 objects ran at once; the busiest lanes are merged.</p>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~      const host = d.querySelector('#t-obj');~');
DBMS_OUTPUT.PUT_LINE(q'~      const ty = d.querySelector('#o-ty'), qq = d.querySelector('#o-q');~');
DBMS_OUTPUT.PUT_LINE(q'~      let st = '';~');
DBMS_OUTPUT.PUT_LINE(q'~      const draw = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const q = qq.value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~        const base = o.tasks.filter((t) => (!ty.value || t.type === ty.value) && (!q || (t.name + ' ' + (t.error || '') + ' ' + t.hist.join(' ')).toLowerCase().includes(q)));~');
DBMS_OUTPUT.PUT_LINE(q'~        const nf = base.filter((t) => t.status === 'FAILED').length, nd = base.filter((t) => t.status === 'COMPLETED').length;~');
DBMS_OUTPUT.PUT_LINE(q'~        d.querySelector('#o-st-host').innerHTML = seg('o-st', [['', 'All', base.length], ['COMPLETED', 'Gathered', nd], ['FAILED', 'Failed', nf]].concat(base.length - nf - nd ? [['other', 'Other', base.length - nf - nd]] : []), st);~');
DBMS_OUTPUT.PUT_LINE(q'~        wireSeg(d, 'o-st', (val) => { st = val; host._t.limit = 300; draw(); });~');
DBMS_OUTPUT.PUT_LINE(q'~        const list = base.filter((t) => !st || (st === 'other' ? t.status !== 'FAILED' && t.status !== 'COMPLETED' : t.status === st));~');
DBMS_OUTPUT.PUT_LINE(q'~        d.querySelector('#o-n').textContent = plural(list.length, 'object');~');
DBMS_OUTPUT.PUT_LINE(q'~        const dmax = Math.max(0.001, ...list.map((t) => t.secs || 0));~');
DBMS_OUTPUT.PUT_LINE(q'~        renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~          rows: list, sort: ['secs', -1], limit: 300, empty: 'No object matches.',~');
DBMS_OUTPUT.PUT_LINE(q'~          cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'name', label: 'Object', cls: 'wrap', html: (t) => pieceName(t, true) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'type', label: 'Type', html: (t) => esc(t.type.toLowerCase()) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'status', label: 'Status', html: (t) => (t.status === 'COMPLETED' ? sevBadge('good', 'gathered') : sevBadge(t.status === 'FAILED' ? 'crit' : 'warn', t.status.toLowerCase())) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'start', label: 'Started', cls: 't', html: (t) => esc(fmtClock(t.start, true)) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'secs', label: 'Duration', num: true, html: (t) => '<span class="durbar">' + esc(fmtDur(t.secs)) + '<span><b style="inline-size:' + (100 * (t.secs || 0) / dmax).toFixed(1) + '%"></b></span></span>' },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'size', label: 'Size', num: true, tip: 'TARGET_SIZE as recorded by DBMS_STATS (blocks)', html: (t) => fmtN(t.size) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'hist', label: 'Histograms', val: (t) => t.hist.length, html: (t) => (t.hist.length ? '<span data-tip="' + esc(esc(t.hist.join(', '))) + '">' + plural(t.hist.length, 'column') + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'error', label: 'Error or extended statistics', cls: 'wrap', html: (t) => (t.error ? '<span class="err">' + esc(t.error) + '</span>' : esc(t.xstats)) }~');
DBMS_OUTPUT.PUT_LINE(q'~          ]~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      host._t = { sort: ['secs', -1], limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~      ty.onchange = () => { host._t.limit = 300; draw(); };~');
DBMS_OUTPUT.PUT_LINE(q'~      let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~      qq.oninput = () => { clearTimeout(qt); qt = setTimeout(draw, 180); };~');
DBMS_OUTPUT.PUT_LINE(q'~      draw();~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ backlog~');
DBMS_OUTPUT.PUT_LINE(q'~  // The statement that would gather an object (or a group of its partitions).~');
DBMS_OUTPUT.PUT_LINE(q'~  // Shown and copied only: the report itself changes nothing.~');
DBMS_OUTPUT.PUT_LINE(q'~  const sqlq = (x) => "'" + String(x).replace(/'/g, "''") + "'";~');
DBMS_OUTPUT.PUT_LINE(q'~  function fixCmd(b) {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (b.cat === 'fixed') return 'exec dbms_stats.gather_fixed_objects_stats';~');
DBMS_OUTPUT.PUT_LINE(q'~    const args = ['ownname => ' + sqlq(b.owner), 'tabname => ' + sqlq(b.table)];~');
DBMS_OUTPUT.PUT_LINE(q'~    const sub = b.group ? b.type === 'SUBPARTITION' : !!b.sub;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!b.group && (b.sub || b.part)) args.push('partname => ' + sqlq(b.sub || b.part));~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sub) args.push("granularity => 'SUBPARTITION'");~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (!b.group && b.part) args.push("granularity => 'PARTITION'");~');
DBMS_OUTPUT.PUT_LINE(q'~    // FORCE gathers through a lock without removing it~');
DBMS_OUTPUT.PUT_LINE(q'~    if (b.locked) args.push('force => TRUE');~');
DBMS_OUTPUT.PUT_LINE(q'~    return 'exec dbms_stats.gather_table_stats(' + args.join(', ') + ')';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Statements for several objects, with the container switch they need~');
DBMS_OUTPUT.PUT_LINE(q'~  function fixScript(list, cmd) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const byCon = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    list.forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!byCon.has(b.con)) byCon.set(b.con, new Set());~');
DBMS_OUTPUT.PUT_LINE(q'~      byCon.get(b.con).add((cmd || fixCmd)(b));~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    byCon.forEach((cmds, con) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (META.cdb === 'YES' && byCon.size > 1 || (META.cdb === 'YES' && con !== META.conId)) out.push('alter session set container = ' + conName(con) + ';');~');
DBMS_OUTPUT.PUT_LINE(q'~      cmds.forEach((c) => out.push(c));~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    return out.join('\n');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function stalePct(b) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const p = b.prefs.find((x) => x.pref === 'STALE_PERCENT');~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = Number(p ? p.value : PREFS.get('STALE_PERCENT'));~');
DBMS_OUTPUT.PUT_LINE(q'~    return isFinite(v) && v > 0 ? v : 10;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Partitions and subpartitions of one table with the same reason: one row~');
DBMS_OUTPUT.PUT_LINE(q'~  function groupBacklog(list) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const by = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    list.forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!b.part && !b.sub) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = b.con + '|' + b.owner + '.' + b.table + '|' + b.cat + '|' + b.type;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!by.has(k)) by.set(k, []);~');
DBMS_OUTPUT.PUT_LINE(q'~      by.get(k).push(b);~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const done = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    list.forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = b.con + '|' + b.owner + '.' + b.table + '|' + b.cat + '|' + b.type;~');
DBMS_OUTPUT.PUT_LINE(q'~      const m = (b.part || b.sub) ? by.get(k) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!m || m.length < 3) { out.push(b); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      if (done.has(k)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      done.add(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      const sum = (f) => m.reduce((a, x) => a + (x[f] || 0), 0);~');
DBMS_OUTPUT.PUT_LINE(q'~      const analyzed = m.some((x) => !x.analyzed) ? null : Math.min(...m.map((x) => x.analyzed));~');
DBMS_OUTPUT.PUT_LINE(q'~      const atts = m.map((x) => x.attempt).filter(Boolean).sort((x, y) => y.start - x.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const rowsN = sum('rows'), dml = sum('dml');~');
DBMS_OUTPUT.PUT_LINE(q'~      out.push({~');
DBMS_OUTPUT.PUT_LINE(q'~        group: true, key: k, members: m, con: b.con, owner: b.owner, table: b.table, type: b.type, cat: b.cat, om: b.om,~');
DBMS_OUTPUT.PUT_LINE(q'~        name: b.owner + '.' + b.table, rows: rowsN || null, dml: dml, ins: sum('ins'), upd: sum('upd'), del: sum('del'), trunc: m.some((x) => x.trunc),~');
DBMS_OUTPUT.PUT_LINE(q'~        pct: rowsN ? (100 * dml) / rowsN : null, analyzed: analyzed, missing: analyzed == null,~');
DBMS_OUTPUT.PUT_LINE(q'~        dmlTs: Math.max(0, ...m.map((x) => x.dmlTs || 0)) || null, attempt: atts[0] || null,~');
DBMS_OUTPUT.PUT_LINE(q'~        prefs: b.prefs, locked: b.locked~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // When the DML-monitoring counters were last written, for the staleness caveat~');
DBMS_OUTPUT.PUT_LINE(q'~  function monText() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const newest = MON.map((m) => m.newest).filter(Boolean);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!newest.length) return 'As of the last DML-monitoring flush. ';~');
DBMS_OUTPUT.PUT_LINE(q'~    return 'As of the last DML-monitoring flush, newest counters ' + esc(fmtT(Math.max(...newest))) + '; later changes are still in memory. ';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~  function viewBacklog(q) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = { cat: q.get('cat') || '', con: q.get('con') || '', text: q.get('q') || '' };~');
DBMS_OUTPUT.PUT_LINE(q'~    const consAll = [...new Set(BL.map((b) => b.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = missingBox() + sec('Needs statistics now', 'Stale or without statistics, and why. ' + monText() + 'Partitions of one table with the same reason form a group.',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="cats" id="cats"></div><p class="cat-text" id="cat-text"></p>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="filters">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (consAll.length > 1 ? '<label>Container <select id="b-con"><option value="">All</option>' + consAll.map((c) => '<option value="' + c + '">' + esc(conName(c)) + '</option>').join('') + '</select></label>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<input type="search" id="b-q" placeholder="Filter by owner, table or partition" aria-label="Filter objects">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<button type="button" id="b-copy" class="copy-all">Copy gather statements</button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="count" id="b-n"></span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (blTruncated ? '<p class="note" style="margin-block-end:1rem">Only the first ' + fmtN(BL.length) + ' objects are in this report (application schemas first). Raise max_backlog to see all.</p>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div id="t-bl"></div>') +~');
DBMS_OUTPUT.PUT_LINE(q'~      sec('Close to stale', 'At least half of STALE_PERCENT changed by the flushed counters alone. Unflushed changes may already have pushed them over.',~');
DBMS_OUTPUT.PUT_LINE(q'~        '<div id="t-near"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const sel = (id) => v.querySelector(id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#b-con')) sel('#b-con').value = f.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#b-q').value = f.text;~');
DBMS_OUTPUT.PUT_LINE(q'~    const host = sel('#t-bl');~');
DBMS_OUTPUT.PUT_LINE(q'~    host._t = { sort: parseSort(q.get('s'), null), limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~    function apply() {~');
DBMS_OUTPUT.PUT_LINE(q'~      f.con = sel('#b-con') ? sel('#b-con').value : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      f.text = sel('#b-q').value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~      const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.cat) params.set('cat', f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.con) params.set('con', f.con);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.text) params.set('q', f.text);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (host._t.sort) params.set('s', sortParam(host._t.sort));~');
DBMS_OUTPUT.PUT_LINE(q'~      setBaseHash('#backlog' + (params.toString() ? '?' + params.toString() : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~      const scoped = BL.filter((b) => (!f.con || String(b.con) === f.con) && (!f.text || b.name.toLowerCase().includes(f.text)));~');
DBMS_OUTPUT.PUT_LINE(q'~      const base = scoped.filter((b) => showOM || !b.om);~');
DBMS_OUTPUT.PUT_LINE(q'~      const cnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~      base.forEach((b) => { cnt[b.cat] = (cnt[b.cat] || 0) + 1; });~');
DBMS_OUTPUT.PUT_LINE(q'~      const cats = CAT_ORDER.filter((c) => cnt[c] || f.cat === c);~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').innerHTML = cats.length ? '<button type="button" class="cat" data-cat="" aria-pressed="' + !f.cat + '">All<span class="n">' + fmtN(base.length) + '</span></button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        cats.map((c) => '<button type="button" class="cat" data-cat="' + c + '" aria-pressed="' + (f.cat === c) + '">' + sevBadge(CATS[c].sev, CATS[c].title) + '<span class="n">' + fmtN(cnt[c] || 0) + '</span></button>').join('') : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cat-text').textContent = f.cat ? CATS[f.cat].text : (base.length ? 'Pick a reason.' : 'Nothing needs statistics with these filters.');~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').querySelectorAll('[data-cat]').forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        b.onclick = () => { f.cat = b.getAttribute('data-cat'); host._t.limit = 300; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = base.filter((b) => !f.cat || b.cat === f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      const rowsOut = groupBacklog(list);~');
DBMS_OUTPUT.PUT_LINE(q'~      const groups = rowsOut.filter((r) => r.group).length;~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#b-n').innerHTML = esc(plural(list.length, 'object')) + (groups ? ', ' + esc(plural(groups, 'group')) : '') + omHint(scoped.length - base.length);~');
DBMS_OUTPUT.PUT_LINE(q'~      const copyAll = sel('#b-copy');~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.hidden = !rowsOut.length;~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.setAttribute('data-copy', fixScript(rowsOut));~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.setAttribute('data-tip', esc('<b>' + plural(rowsOut.length, 'statement') + ' for the rows below</b><br>Review first: locked statistics are often locked on purpose.'));~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: rowsOut, limit: 300, empty: 'Nothing matches these filters.',~');
DBMS_OUTPUT.PUT_LINE(q'~        href: (b) => (b.attempt && b.attempt.op ? '#run/' + b.attempt.op.key : null),~');
DBMS_OUTPUT.PUT_LINE(q'~        kids: (r) => (r.group ? r.members : null), rowKey: (r) => r.key,~');
DBMS_OUTPUT.PUT_LINE(q'~        onSort: () => apply(),~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'name', label: 'Object', cls: 'wrap', html: (b) => objCell(b, consAll.length > 1) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'cat', label: 'Why', val: (b) => CAT_ORDER.indexOf(b.cat), html: (b) => sevBadge(CATS[b.cat].sev, CATS[b.cat].title, CATS[b.cat].text) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'rows', label: 'Rows', num: true, tip: 'NUM_ROWS in the current statistics', html: (b) => fmtN(b.rows) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'pct', label: 'Changed', num: true, tip: 'Inserts + updates + deletes since the last gather, against the row count in the statistics. The tick is STALE_PERCENT.', val: (b) => b.pct,~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~              if (!b.dml) return b.trunc ? 'truncated' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~              const th = stalePct(b);~');
DBMS_OUTPUT.PUT_LINE(q'~              const bar = b.pct != null ? '<span class="pctbar" aria-hidden="true"><b style="inline-size:' + Math.min(100, b.pct).toFixed(1) + '%"></b><i style="inset-inline-start:' + Math.min(100, th) + '%"></i></span>' : '';~');
DBMS_OUTPUT.PUT_LINE(q'~              return '<span class="pctcell" data-tip="' + esc('Inserts ' + fmtN(b.ins) + '<br>Updates ' + fmtN(b.upd) + '<br>Deletes ' + fmtN(b.del) + (b.trunc ? '<br>Truncated' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~                (b.pct != null ? '<br>' + (b.pct >= 1000 ? 'over 999' : b.pct.toFixed(1)) + '% changed; stale from ' + th + '%' : '')) + '">' + fmtN(b.dml) +~');
DBMS_OUTPUT.PUT_LINE(q'~                (b.pct != null ? ' <span class="muted">(' + (b.pct >= 1000 ? '>999' : b.pct.toFixed(b.pct < 10 ? 1 : 0)) + '%)</span>' : '') + bar + '</span>';~');
DBMS_OUTPUT.PUT_LINE(q'~            } },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'analyzed', label: 'Analyzed', cls: 't', html: (b) => (b.analyzed ? esc(fmtT(b.analyzed)) : '<span class="err">never</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'dmlTs', label: 'Last DML', cls: 't', tip: 'Time of the last DML-monitoring row for it', html: (b) => esc(fmtT(b.dmlTs)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'attempt', label: 'Last attempt', cls: 'wrap', tip: 'The last gather of this object in the period', val: (b) => (b.attempt ? b.attempt.start : null),~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => (b.attempt ? esc(fmtT(b.attempt.start)) + ' ' + (b.attempt.status === 'FAILED' ? '<span class="err">failed: ' + esc(b.attempt.error || '') + '</span>' : '<span class="muted">' + esc(String(b.attempt.status || '').toLowerCase()) + '</span>') : '<span class="muted">none in the period</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'prefs', label: 'Preferences', cls: 'wrap prefs', val: (b) => b.prefs.length,~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~              const key = b.prefs.filter((p) => /^(STALE_PERCENT|INCREMENTAL|GRANULARITY|PUBLISH)$/.test(p.pref));~');
DBMS_OUTPUT.PUT_LINE(q'~              const rest = b.prefs.length - key.length;~');
DBMS_OUTPUT.PUT_LINE(q'~              return '<div class="pills">' + (b.locked ? '<span class="pill">locked ' + esc(b.locked.toLowerCase()) + '</span> ' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~                key.map((p) => '<span class="pill">' + esc(p.pref) + '=' + esc(p.value) + '</span>').join(' ') +~');
DBMS_OUTPUT.PUT_LINE(q'~                (rest ? ' <span class="pill" data-tip="' + esc(b.prefs.map((p) => esc(p.pref) + ' = ' + esc(p.value)).join('<br>')) + '">' + (key.length ? '+' : '') + plural(rest, 'preference') + '</span>' : '') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~            } },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'fix', label: 'Gather', val: () => null, html: (b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~            const cmd = fixScript([b]);~');
DBMS_OUTPUT.PUT_LINE(q'~            return '<button type="button" class="copy" data-copy="' + esc(cmd) + '" data-tip="' + esc('<code>' + esc(cmd).replace(/\n/g, '<br>') + '</code><br><span class="muted">Click to copy' + (b.locked ? '. Locked: often on purpose, check first' : '') + '</span>') + '">Copy</button>';~');
DBMS_OUTPUT.PUT_LINE(q'~          } }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      applyNear();~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const nearHost = sel('#t-near');~');
DBMS_OUTPUT.PUT_LINE(q'~    // Partitions of one table: one row that opens up (three or more)~');
DBMS_OUTPUT.PUT_LINE(q'~    function groupNear(list) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const by = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~      list.forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!b.part && !b.sub) return;~');
DBMS_OUTPUT.PUT_LINE(q'~        const k = b.con + '|' + b.owner + '.' + b.table + '|' + b.type;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!by.has(k)) by.set(k, []);~');
DBMS_OUTPUT.PUT_LINE(q'~        by.get(k).push(b);~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      const done = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~      const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~      list.forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const k = b.con + '|' + b.owner + '.' + b.table + '|' + b.type;~');
DBMS_OUTPUT.PUT_LINE(q'~        const m = (b.part || b.sub) ? by.get(k) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!m || m.length < 3) { out.push(b); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~        if (done.has(k)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~        done.add(k);~');
DBMS_OUTPUT.PUT_LINE(q'~        const sum = (fld) => m.reduce((a, x) => a + (x[fld] || 0), 0);~');
DBMS_OUTPUT.PUT_LINE(q'~        const g = {~');
DBMS_OUTPUT.PUT_LINE(q'~          group: true, key: k, members: m, con: b.con, owner: b.owner, table: b.table, type: b.type, om: b.om, name: b.owner + '.' + b.table,~');
DBMS_OUTPUT.PUT_LINE(q'~          rows: sum('rows'), ins: sum('ins'), upd: sum('upd'), del: sum('del'), dml: sum('dml'), th: b.th,~');
DBMS_OUTPUT.PUT_LINE(q'~          share: Math.max(...m.map((x) => x.share || 0)), analyzed: Math.min(...m.map((x) => x.analyzed || 9e15)), dmlTs: Math.max(...m.map((x) => x.dmlTs || 0)) || null~');
DBMS_OUTPUT.PUT_LINE(q'~        };~');
DBMS_OUTPUT.PUT_LINE(q'~        g.pct = g.rows ? (100 * g.dml) / g.rows : null;~');
DBMS_OUTPUT.PUT_LINE(q'~        out.push(g);~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      return out;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    function applyNear() {~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = NEAR.filter((b) => (showOM || !b.om) && (!f.con || String(b.con) === f.con) && (!f.text || b.name.toLowerCase().includes(f.text)));~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(nearHost, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: groupNear(list), sort: ['share', -1], limit: 50,~');
DBMS_OUTPUT.PUT_LINE(q'~        kids: (r) => (r.group ? r.members : null), rowKey: (r) => r.key,~');
DBMS_OUTPUT.PUT_LINE(q'~        empty: missing.includes('near') ? 'Not collected.' : 'Nothing is close to its stale threshold with these filters.',~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'name', label: 'Object', cls: 'wrap', html: (b) => objCell(b, consAll.length > 1 || CONS.size > 1) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'rows', label: 'Rows', num: true, tip: 'NUM_ROWS in the current statistics', html: (b) => fmtN(b.rows) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'share', label: 'Changed', num: true, tip: 'Inserts + updates + deletes in the flushed counters, against the row count. A full bar is STALE_PERCENT; for a group, the partition closest to it.',~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (b) => '<span class="pctcell" data-tip="' + esc('Inserts ' + fmtN(b.ins) + '<br>Updates ' + fmtN(b.upd) + '<br>Deletes ' + fmtN(b.del) + '<br>' + b.pct.toFixed(1) + '% changed; stale from ' + b.th + '%' +~');
DBMS_OUTPUT.PUT_LINE(q'~              (b.group ? '<br>Closest partition: ' + (100 * b.share).toFixed(0) + '% of the way' : '')) + '">' +~');
DBMS_OUTPUT.PUT_LINE(q'~              fmtN(b.dml) + ' <span class="muted">(' + b.pct.toFixed(1) + '%)</span><span class="pctbar" aria-hidden="true"><b style="inline-size:' + Math.min(100, 100 * b.share).toFixed(1) + '%"></b></span></span>' },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'th', label: 'Stale at', num: true, tip: 'STALE_PERCENT: the table preference, else the global one', html: (b) => esc(b.th) + '%' },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'analyzed', label: 'Analyzed', cls: 't', html: (b) => esc(fmtT(b.analyzed)) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'dmlTs', label: 'Last DML', cls: 't', tip: 'Time of the DML-monitoring row', html: (b) => esc(fmtT(b.dmlTs)) }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#b-con')) sel('#b-con').onchange = () => { host._t.limit = 300; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~    let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#b-q').oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 180); };~');
DBMS_OUTPUT.PUT_LINE(q'~    apply();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ columns~');
DBMS_OUTPUT.PUT_LINE(q'~  // A default gather fixes most of these; a height-balanced histogram also~');
DBMS_OUTPUT.PUT_LINE(q'~  // needs AUTO_SAMPLE_SIZE in case a fixed ESTIMATE_PERCENT is what built it.~');
DBMS_OUTPUT.PUT_LINE(q'~  function colFixCmd(c) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const args = ['ownname => ' + sqlq(c.owner), 'tabname => ' + sqlq(c.table)];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (c.cat === 'legacyhb') args.push('estimate_percent => dbms_stats.auto_sample_size');~');
DBMS_OUTPUT.PUT_LINE(q'~    return 'exec dbms_stats.gather_table_stats(' + args.join(', ') + ')';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Columns of one table with the same reason: one row that opens up~');
DBMS_OUTPUT.PUT_LINE(q'~  function groupCols(list) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const by = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    list.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = c.con + '|' + c.name + '|' + c.cat;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!by.has(k)) by.set(k, []);~');
DBMS_OUTPUT.PUT_LINE(q'~      by.get(k).push(c);~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const done = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    list.forEach((c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = c.con + '|' + c.name + '|' + c.cat;~');
DBMS_OUTPUT.PUT_LINE(q'~      const m = by.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (m.length < 2) { out.push(c); return; }~');
DBMS_OUTPUT.PUT_LINE(q'~      if (done.has(k)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      done.add(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      const an = m.map((x) => x.analyzed).filter(Boolean);~');
DBMS_OUTPUT.PUT_LINE(q'~      out.push({~');
DBMS_OUTPUT.PUT_LINE(q'~        group: true, key: k, members: m, con: c.con, owner: c.owner, table: c.table, name: c.name, full: c.name, cat: c.cat, om: c.om,~');
DBMS_OUTPUT.PUT_LINE(q'~        prefs: c.prefs, tabAnalyzed: c.tabAnalyzed, rows: c.rows, analyzed: an.length === m.length ? Math.min(...an) : null~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    return out;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewColumns(q) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const f = { cat: q.get('cat') || '', con: q.get('con') || '', text: q.get('q') || '' };~');
DBMS_OUTPUT.PUT_LINE(q'~    const consAll = [...new Set(COLS.map((c) => c.con))].sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~    const om = COLAGG.filter((a) => a.om).reduce((a, x) => a + x.n, 0);~');
DBMS_OUTPUT.PUT_LINE(q'~    v.innerHTML = missingBox() + sec('Column statistics', 'Column statistics that lag behind their table, or histograms that cannot describe the column. Table level only; tables without statistics are under Needs statistics.',~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="cats" id="cats"></div><p class="cat-text" id="cat-text"></p>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div class="filters">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (consAll.length > 1 ? '<label>Container <select id="c-con"><option value="">All</option>' + consAll.map((c) => '<option value="' + c + '">' + esc(conName(c)) + '</option>').join('') + '</select></label>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<input type="search" id="c-q" placeholder="Filter by owner, table or column" aria-label="Filter columns">' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<button type="button" id="c-copy" class="copy-all">Copy gather statements</button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<span class="count" id="c-n"></span></div>' +~');
DBMS_OUTPUT.PUT_LINE(q'~      (colTruncated ? '<p class="note" style="margin-block-end:1rem">Only the first ' + fmtN(COLS.length) + ' columns are in this report (application schemas first); ' +~');
DBMS_OUTPUT.PUT_LINE(q'~        fmtN(COLAGG.reduce((a, x) => a + x.n, 0)) + ' in all' + (om ? ', ' + fmtN(om) + ' of them in Oracle schemas' : '') + '. Raise max_backlog to see all.</p>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<div id="t-cols"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~    const sel = (id) => v.querySelector(id);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#c-con')) sel('#c-con').value = f.con;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#c-q').value = f.text;~');
DBMS_OUTPUT.PUT_LINE(q'~    const host = sel('#t-cols');~');
DBMS_OUTPUT.PUT_LINE(q'~    host._t = { sort: parseSort(q.get('s'), null), limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~    function apply() {~');
DBMS_OUTPUT.PUT_LINE(q'~      f.con = sel('#c-con') ? sel('#c-con').value : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      f.text = sel('#c-q').value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~      const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.cat) params.set('cat', f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.con) params.set('con', f.con);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (f.text) params.set('q', f.text);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (host._t.sort) params.set('s', sortParam(host._t.sort));~');
DBMS_OUTPUT.PUT_LINE(q'~      setBaseHash('#columns' + (params.toString() ? '?' + params.toString() : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~      const scoped = COLS.filter((c) => (!f.con || String(c.con) === f.con) && (!f.text || c.full.toLowerCase().includes(f.text)));~');
DBMS_OUTPUT.PUT_LINE(q'~      const base = scoped.filter((c) => showOM || !c.om);~');
DBMS_OUTPUT.PUT_LINE(q'~      const cnt = {};~');
DBMS_OUTPUT.PUT_LINE(q'~      base.forEach((c) => { cnt[c.cat] = (cnt[c.cat] || 0) + 1; });~');
DBMS_OUTPUT.PUT_LINE(q'~      const cats = COLCAT_ORDER.filter((c) => cnt[c] || f.cat === c);~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').innerHTML = cats.length ? '<button type="button" class="cat" data-cat="" aria-pressed="' + !f.cat + '">All<span class="n">' + fmtN(base.length) + '</span></button>' +~');
DBMS_OUTPUT.PUT_LINE(q'~        cats.map((c) => '<button type="button" class="cat" data-cat="' + c + '" aria-pressed="' + (f.cat === c) + '">' + sevBadge(COLCATS[c].sev, COLCATS[c].title) + '<span class="n">' + fmtN(cnt[c] || 0) + '</span></button>').join('') : '';~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cat-text').textContent = f.cat ? COLCATS[f.cat].text : (base.length ? 'Pick a reason.' : missing.includes('cols') ? 'Not collected.' : 'No column statistics problem with these filters.');~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#cats').querySelectorAll('[data-cat]').forEach((b) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        b.onclick = () => { f.cat = b.getAttribute('data-cat'); host._t.limit = 300; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~      const list = base.filter((c) => !f.cat || c.cat === f.cat);~');
DBMS_OUTPUT.PUT_LINE(q'~      const rowsOut = groupCols(list);~');
DBMS_OUTPUT.PUT_LINE(q'~      const tables = new Set(list.map((c) => c.con + '|' + c.name)).size;~');
DBMS_OUTPUT.PUT_LINE(q'~      sel('#c-n').innerHTML = esc(plural(list.length, 'column')) + (list.length ? ' in ' + esc(plural(tables, 'table')) : '') + omHint(scoped.length - base.length);~');
DBMS_OUTPUT.PUT_LINE(q'~      const copyAll = sel('#c-copy');~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.hidden = !rowsOut.length;~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.setAttribute('data-copy', fixScript(rowsOut, colFixCmd));~');
DBMS_OUTPUT.PUT_LINE(q'~      copyAll.setAttribute('data-tip', esc('<b>One statement per table below</b><br>A default gather: a METHOD_OPT or ESTIMATE_PERCENT table preference that caused this stays in force.'));~');
DBMS_OUTPUT.PUT_LINE(q'~      renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~        rows: rowsOut, limit: 300, empty: 'Nothing matches these filters.',~');
DBMS_OUTPUT.PUT_LINE(q'~        kids: (r) => (r.group ? r.members : null), rowKey: (r) => r.key,~');
DBMS_OUTPUT.PUT_LINE(q'~        onSort: () => apply(),~');
DBMS_OUTPUT.PUT_LINE(q'~        cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'full', label: 'Column', cls: 'wrap', html: (c) => '<code>' + tabLink(c.con, c.name) + (c.group ? '' : '.' + esc(c.col)) + '</code>' +~');
DBMS_OUTPUT.PUT_LINE(q'~            (c.group ? ' <span class="pill" data-tip="' + esc(c.members.slice(0, 15).map((x) => esc(x.col)).join('<br>') + (c.members.length > 15 ? '<br>+' + fmtN(c.members.length - 15) + ' more' : '')) + '">' + esc(plural(c.members.length, 'column')) + '</span>' : c.dtype ? ' <span class="pill">' + esc(c.dtype.toLowerCase()) + '</span>' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~            (consAll.length > 1 ? ' <span class="pill">' + esc(conName(c.con)) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'cat', label: 'Why', val: (c) => COLCAT_ORDER.indexOf(c.cat), html: (c) => sevBadge(COLCATS[c.cat].sev, COLCATS[c.cat].title, COLCATS[c.cat].text) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'hist', label: 'Histogram', html: (c) => (c.group ? '' : !c.hist ? '' : c.hist === 'NONE' ? '<span class="muted">none</span>' :~');
DBMS_OUTPUT.PUT_LINE(q'~            esc(c.hist.toLowerCase()) + ' <span class="muted">' + esc(plural(c.buckets, 'bucket')) + '</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'ndv', label: 'Distinct', num: true, tip: 'NUM_DISTINCT', html: (c) => fmtN(c.ndv) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'nulls', label: 'Nulls', num: true, tip: 'NUM_NULLS', html: (c) => fmtN(c.nulls) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'rows', label: 'Table rows', num: true, tip: 'NUM_ROWS of the table', html: (c) => fmtN(c.rows) },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'analyzed', label: 'Column analyzed', cls: 't', html: (c) => (c.analyzed ? esc(fmtT(c.analyzed)) : '<span class="err">never</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'tabAnalyzed', label: 'Table analyzed', cls: 't', html: (c) => esc(fmtT(c.tabAnalyzed)) +~');
DBMS_OUTPUT.PUT_LINE(q'~            (c.analyzed && c.tabAnalyzed - c.analyzed > 36e5 ? ' <span class="muted">(' + esc(fmtDur((c.tabAnalyzed - c.analyzed) / 1000)) + ' later)</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'prefs', label: 'Preferences', cls: 'wrap prefs', val: (c) => c.prefs.length,~');
DBMS_OUTPUT.PUT_LINE(q'~            html: (c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~              const key = c.prefs.filter((p) => /^(METHOD_OPT|ESTIMATE_PERCENT)$/.test(p.pref));~');
DBMS_OUTPUT.PUT_LINE(q'~              const rest = c.prefs.length - key.length;~');
DBMS_OUTPUT.PUT_LINE(q'~              return '<div class="pills">' + key.map((p) => '<span class="pill">' + esc(p.pref) + '=' + esc(p.value) + '</span>').join(' ') +~');
DBMS_OUTPUT.PUT_LINE(q'~                (rest ? ' <span class="pill" data-tip="' + esc(c.prefs.map((p) => esc(p.pref) + ' = ' + esc(p.value)).join('<br>')) + '">' + (key.length ? '+' : '') + plural(rest, 'preference') + '</span>' : '') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~            } },~');
DBMS_OUTPUT.PUT_LINE(q'~          { key: 'fix', label: 'Gather', val: () => null, html: (c) => {~');
DBMS_OUTPUT.PUT_LINE(q'~            const cmd = fixScript([c], colFixCmd);~');
DBMS_OUTPUT.PUT_LINE(q'~            return '<button type="button" class="copy" data-copy="' + esc(cmd) + '" data-tip="' + esc('<code>' + esc(cmd).replace(/\n/g, '<br>') + '</code><br><span class="muted">Click to copy. Gathers the whole table with its preferences.</span>') + '">Copy</button>';~');
DBMS_OUTPUT.PUT_LINE(q'~          } }~');
DBMS_OUTPUT.PUT_LINE(q'~        ]~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
END;
/
BEGIN
DBMS_OUTPUT.PUT_LINE(q'~    if (sel('#c-con')) sel('#c-con').onchange = () => { host._t.limit = 300; apply(); };~');
DBMS_OUTPUT.PUT_LINE(q'~    let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~    sel('#c-q').oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 180); };~');
DBMS_OUTPUT.PUT_LINE(q'~    apply();~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // ------------------------------------------------------------ one table~');
DBMS_OUTPUT.PUT_LINE(q'~  // Everything the report knows about one table: its statistics now, the~');
DBMS_OUTPUT.PUT_LINE(q'~  // preferences in force, whether incremental statistics are set up and in~');
DBMS_OUTPUT.PUT_LINE(q'~  // use, and every gather that touched it in the period.~');
DBMS_OUTPUT.PUT_LINE(q'~  let TABLE_INDEX = null;~');
DBMS_OUTPUT.PUT_LINE(q'~  function tableIndex() {~');
DBMS_OUTPUT.PUT_LINE(q'~    if (TABLE_INDEX) return TABLE_INDEX;~');
DBMS_OUTPUT.PUT_LINE(q'~    const by = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    const add = (con, name) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const k = conKey(con, name);~');
DBMS_OUTPUT.PUT_LINE(q'~      let x = by.get(k);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x) by.set(k, x = { con: con, name: name, om: isOM(con, name.split('.')[0]), tab: TABMAP.get(k) || null, gathers: 0, last: null, prefs: TPREFMAP.get(k) || [] });~');
DBMS_OUTPUT.PUT_LINE(q'~      return x;~');
DBMS_OUTPUT.PUT_LINE(q'~    };~');
DBMS_OUTPUT.PUT_LINE(q'~    TABS.forEach((t) => add(t.con, t.name));~');
DBMS_OUTPUT.PUT_LINE(q'~    const seen = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!t.tab || !t.op || t.op.kind === 'other') return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const x = add(t.con, t.tab);~');
DBMS_OUTPUT.PUT_LINE(q'~      const rk = t.tab + '|' + t.op.key;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (seen.has(rk)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      seen.add(rk);~');
DBMS_OUTPUT.PUT_LINE(q'~      x.gathers++;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!x.last || t.op.start > x.last.start) x.last = t.op;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    BL.forEach((b) => add(b.con, b.owner + '.' + b.table));~');
DBMS_OUTPUT.PUT_LINE(q'~    NEAR.forEach((b) => add(b.con, b.owner + '.' + b.table));~');
DBMS_OUTPUT.PUT_LINE(q'~    COLS.forEach((c) => add(c.con, c.name));~');
DBMS_OUTPUT.PUT_LINE(q'~    TABLE_INDEX = [...by.values()];~');
DBMS_OUTPUT.PUT_LINE(q'~    return TABLE_INDEX;~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  const isTrue = (v) => /^TRUE$/i.test(v || '');~');
DBMS_OUTPUT.PUT_LINE(q'~  // The gathers of one table, one row per operation~');
DBMS_OUTPUT.PUT_LINE(q'~  function tableRuns(con, name) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const runs = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    TASKS.forEach((t) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (t.con !== con || t.tab !== name || !t.op || t.op.kind === 'other') return;~');
DBMS_OUTPUT.PUT_LINE(q'~      let r = runs.get(t.op);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!r) runs.set(t.op, r = { op: t.op, glob: [], parts: [], idx: [], secs: 0, failed: 0, hist: 0, n: 0 });~');
DBMS_OUTPUT.PUT_LINE(q'~      (/^TABLE/.test(t.type) ? (t.piece ? r.parts : r.glob) : r.idx).push(t);~');
DBMS_OUTPUT.PUT_LINE(q'~      r.secs += t.secs || 0; r.n++;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (t.status === 'FAILED') r.failed++;~');
DBMS_OUTPUT.PUT_LINE(q'~      if (t.hist.length) r.hist++;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    return [...runs.values()].sort((a, b) => a.op.start - b.op.start);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Is the incremental-statistics setup of this table consistent, and do the~');
DBMS_OUTPUT.PUT_LINE(q'~  // gathers show it working?  One row per check.~');
DBMS_OUTPUT.PUT_LINE(q'~  function incChecks(con, key, tab, runs, pref) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const out = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const chk = (sev, what, value, why) => out.push({ sev: sev, what: what, value: value, why: why || '' });~');
DBMS_OUTPUT.PUT_LINE(q'~    const seenParts = new Set();~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((r) => r.parts.forEach((t) => seenParts.add(t.piece)));~');
DBMS_OUTPUT.PUT_LINE(q'~    const parted = tab ? !!tab.ptype : seenParts.size > 0;~');
DBMS_OUTPUT.PUT_LINE(q'~    const nparts = (tab && tab.nparts) || seenParts.size;~');
DBMS_OUTPUT.PUT_LINE(q'~    const inc = pref('INCREMENTAL'), incOn = isTrue(inc.v);~');
DBMS_OUTPUT.PUT_LINE(q'~    const src = (p) => (p.src === 'table' ? 'table preference' : 'global preference');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!parted) {~');
DBMS_OUTPUT.PUT_LINE(q'~      chk('info', 'Partitioned', 'no', 'Incremental statistics apply to partitioned tables only.');~');
DBMS_OUTPUT.PUT_LINE(q'~      if (inc.src === 'table' && incOn) chk('warn', 'INCREMENTAL', inc.v + ' (' + src(inc) + ')', 'No effect on a table without partitions.');~');
DBMS_OUTPUT.PUT_LINE(q'~      return { checks: out, verdict: { sev: 'info', label: 'Not applicable' } };~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    chk('good', 'Partitioned', (tab && tab.ptype ? tab.ptype.toLowerCase() + (tab.subptype && tab.subptype !== 'NONE' ? ' / ' + tab.subptype.toLowerCase() : '') + ', ' : '') + plural(nparts, 'partition') + (tab && tab.interval ? ', interval' : ''), '');~');
DBMS_OUTPUT.PUT_LINE(q'~    chk(incOn ? 'good' : 'warn', 'INCREMENTAL', (inc.v || 'unknown') + ' (' + src(inc) + ')', incOn ? '' : 'Off: a changed partition makes the whole table stale, and the global statistics need a full scan.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const pub = pref('PUBLISH');~');
DBMS_OUTPUT.PUT_LINE(q'~    chk(isTrue(pub.v) ? 'good' : incOn ? 'crit' : 'info', 'PUBLISH', (pub.v || 'unknown') + ' (' + src(pub) + ')', isTrue(pub.v) ? '' : 'Incremental statistics need PUBLISH=TRUE.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const ep = pref('ESTIMATE_PERCENT'), epAuto = /AUTO_SAMPLE_SIZE/i.test(ep.v || '');~');
DBMS_OUTPUT.PUT_LINE(q'~    chk(epAuto ? 'good' : incOn ? 'crit' : 'info', 'ESTIMATE_PERCENT', (ep.v || 'unknown') + ' (' + src(ep) + ')', epAuto ? '' : 'Synopses are only built with AUTO_SAMPLE_SIZE. With a fixed percent every gather rescans the table for the global statistics.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const gr = pref('GRANULARITY'), g = (gr.v || '').toUpperCase();~');
DBMS_OUTPUT.PUT_LINE(q'~    const grOk = /^(AUTO|ALL|DEFAULT|GLOBAL AND PARTITION|APPROX_GLOBAL AND PARTITION)$/.test(g);~');
DBMS_OUTPUT.PUT_LINE(q'~    chk(grOk ? 'good' : 'warn', 'GRANULARITY', (gr.v || 'unknown') + ' (' + src(gr) + ')', grOk ? '' : g === 'GLOBAL' ? 'Partition statistics are never gathered.' : 'Global statistics are not refreshed by these gathers.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const st = pref('INCREMENTAL_STALENESS');~');
DBMS_OUTPUT.PUT_LINE(q'~    chk('info', 'INCREMENTAL_STALENESS', (st.v || 'NULL') + ' (' + src(st) + ')', /USE_STALE_PERCENT/i.test(st.v || '') ? 'A partition is regathered only past STALE_PERCENT.' : 'Any change makes a partition stale and regathered.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const lvl = (TPREFMAP.get(key) || []).find((p) => p.pref === 'INCREMENTAL_LEVEL');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (lvl) chk('info', 'INCREMENTAL_LEVEL', lvl.value + ' (table preference)', lvl.value === 'TABLE' ? 'A table-level synopsis too, for partition exchange.' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~    const syn = SYN.get(key);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (missing.includes('syn')) chk('info', 'Synopses', 'not checked', 'No access to SYS.WRI$_OPTSTAT_SYNOPSIS_HEAD$.');~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (syn) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const full = syn.parts >= nparts;~');
DBMS_OUTPUT.PUT_LINE(q'~      chk(full ? 'good' : 'warn', 'Synopses', fmtN(syn.parts) + ' of ' + plural(nparts, 'partition') + ', newest ' + fmtT(syn.newest),~');
DBMS_OUTPUT.PUT_LINE(q'~        full ? 'Every partition has one: the global statistics come from the synopses.' : 'Partitions without one are rescanned at the next gather of the global statistics (gathered before INCREMENTAL was set, or with a fixed ESTIMATE_PERCENT).');~');
DBMS_OUTPUT.PUT_LINE(q'~    } else chk(incOn ? 'crit' : 'info', 'Synopses', 'none', incOn ? 'No partition has a synopsis: incremental statistics have not been used on this table yet. The next gather scans every partition once to build them.' : 'Built by the first gather with INCREMENTAL=TRUE.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const withGlob = runs.filter((r) => r.glob.length);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!runs.length) chk('info', 'Gathers in the period', 'none', '');~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (incOn) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const full = withGlob.filter((r) => nparts >= 2 && r.parts.length >= 0.9 * nparts);~');
DBMS_OUTPUT.PUT_LINE(q'~      const med = withGlob.map((r) => r.parts.length).sort((a, b) => a - b);~');
DBMS_OUTPUT.PUT_LINE(q'~      const gsecs = withGlob.reduce((a, r) => a + r.glob.reduce((x, t) => x + (t.secs || 0), 0), 0) / Math.max(1, withGlob.length);~');
DBMS_OUTPUT.PUT_LINE(q'~      if (full.length > 1) chk('warn', 'Gathers in the period', fmtN(full.length) + ' of ' + plural(withGlob.length, 'gather') + ' regathered every partition', 'Once is expected (the first incremental gather). Repeated full regathers mean the synopses are rebuilt each time: check ESTIMATE_PERCENT and INCREMENTAL_STALENESS, and the parameters of manual gathers below.');~');
DBMS_OUTPUT.PUT_LINE(q'~      else if (withGlob.length) chk('good', 'Gathers in the period', plural(withGlob.length, 'gather') + ', typically ' + plural(med[Math.floor(med.length / 2)], 'partition') + ' each, global statistics in ' + fmtDur(gsecs), full.length ? 'One gather took every partition: the first incremental gather.' : 'Only changed partitions were regathered.');~');
DBMS_OUTPUT.PUT_LINE(q'~      else chk('info', 'Gathers in the period', plural(runs.length, 'gather') + ', partitions only', 'The global statistics were not touched.');~');
DBMS_OUTPUT.PUT_LINE(q'~    } else if (withGlob.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const gsecs = withGlob.reduce((a, r) => a + r.glob.reduce((x, t) => x + (t.secs || 0), 0), 0) / withGlob.length;~');
DBMS_OUTPUT.PUT_LINE(q'~      chk('info', 'Gathers in the period', plural(withGlob.length, 'gather') + ' of the global statistics, ' + fmtDur(gsecs) + ' each on average', 'The whole table is scanned each time.');~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const worst = out.reduce((w, c) => (SEV_RANK[c.sev] > SEV_RANK[w] ? c.sev : w), 'good');~');
DBMS_OUTPUT.PUT_LINE(q'~    const verdict = worst === 'crit' ? { sev: 'crit', label: 'Broken' } : worst === 'warn' ? { sev: 'warn', label: incOn ? 'Needs attention' : 'Off' } : { sev: 'good', label: incOn ? 'In use' : 'Off' };~');
DBMS_OUTPUT.PUT_LINE(q'~    return { checks: out, verdict: verdict };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Gathers of one table over the period: one column per gather, stacked~');
DBMS_OUTPUT.PUT_LINE(q'~  // by what it took (global, partitions, indexes)~');
DBMS_OUTPUT.PUT_LINE(q'~  function tableRunsSVG(width, runs, metric) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const ax = dayAxis(width);~');
DBMS_OUTPUT.PUT_LINE(q'~    const top = 8, H = 150, bottom = 22;~');
DBMS_OUTPUT.PUT_LINE(q'~    const parts = (r) => (metric === 'secs' ? [r.glob, r.parts, r.idx].map((l) => l.reduce((a, t) => a + (t.secs || 0), 0)) : [r.glob.length, r.parts.length, r.idx.length]);~');
DBMS_OUTPUT.PUT_LINE(q'~    const max = niceMax(Math.max(0, ...runs.map((r) => parts(r).reduce((a, b) => a + b, 0))));~');
DBMS_OUTPUT.PUT_LINE(q'~    const y = (v) => top + (H - top - bottom) * (1 - v / max);~');
DBMS_OUTPUT.PUT_LINE(q'~    const fmt = metric === 'secs' ? fmtDur : compact;~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + width + '" height="' + H + '" role="img" aria-label="Gathers of this table over time">';~');
DBMS_OUTPUT.PUT_LINE(q'~    for (let i = 0; i < ax.nd; i++) {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (isWeekend(ax.d0 + i * DAY)) s += '<rect class="weekend" x="' + (PLOT_L + i * ax.cw) + '" y="' + top + '" width="' + ax.cw + '" height="' + (H - top - bottom) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    [0, max / 2, max].forEach((v) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<line class="' + (v ? 'grid' : 'axis') + '" x1="' + PLOT_L + '" x2="' + (PLOT_L + ax.W) + '" y1="' + y(v) + '" y2="' + y(v) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (PLOT_L - 8) + '" y="' + (y(v) + 4) + '" text-anchor="end">' + esc(v ? fmt(v) : '0') + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const w = Math.max(3, Math.min(10, ax.cw * 0.3));~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((r) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cx = ax.x(r.op.start);~');
DBMS_OUTPUT.PUT_LINE(q'~      const seg = parts(r);~');
DBMS_OUTPUT.PUT_LINE(q'~      let base = 0;~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<rect class="hit" x="' + (cx - 6) + '" y="' + top + '" width="12" height="' + (H - top - bottom) + '" data-href="#run/' + r.op.key + '" data-tip="' + esc(tableRunTip(r)) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      ['f-s1', 'f-s2', 'f-s3'].forEach((cls, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!(seg[i] > 0)) return;~');
DBMS_OUTPUT.PUT_LINE(q'~        const y1 = y(base + seg[i]), y0 = y(base);~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + (r.failed && i === 0 ? 'f-crit' : cls) + '" pointer-events="none" x="' + (cx - w / 2) + '" y="' + y1 + '" width="' + w + '" height="' + Math.max(1, y0 - y1) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~        base += seg[i];~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    s += dayLabels(ax, H - 4);~');
DBMS_OUTPUT.PUT_LINE(q'~    return s + '</svg>';~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function tableRunTip(r) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const o = r.op;~');
DBMS_OUTPUT.PUT_LINE(q'~    const names = [...new Set(r.parts.map((t) => t.piece))];~');
DBMS_OUTPUT.PUT_LINE(q'~    return '<b>' + esc(opLabel(o)) + (o.kind === 'auto' ? '' : ' ' + esc(opTarget(o))) + '</b><br>' + esc(fmtT(o.start, true)) + ', ' + esc(o.v.label) +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>Global statistics: ' + (r.glob.length ? esc(fmtDur(r.glob.reduce((a, t) => a + (t.secs || 0), 0))) + (r.glob.some((t) => t.status === 'FAILED') ? ' <span class="muted">failed</span>' : '') : 'not gathered') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>Partitions: ' + (names.length ? fmtN(names.length) + ' <span class="muted">' + esc(names.slice(0, 6).join(', ')) + (names.length > 6 ? ', +' + fmtN(names.length - 6) : '') + '</span>' : 'none') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>Indexes: ' + (r.idx.length ? fmtN(r.idx.length) : 'none') +~');
DBMS_OUTPUT.PUT_LINE(q'~      '<br>' + esc(fmtDur(r.secs)) + (r.hist ? ', histograms on ' + plural(r.hist, 'object') : '') + (r.failed ? ', <span class="muted">' + plural(r.failed, 'object') + ' failed</span>' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  // Which partition each gather took: partitions down, gathers across~');
DBMS_OUTPUT.PUT_LINE(q'~  function partMatrixSVG(width, runs, nparts) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const seen = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((r) => r.parts.forEach((t) => { const x = seen.get(t.piece); if (!x || t.start > x) seen.set(t.piece, t.start || 0); }));~');
DBMS_OUTPUT.PUT_LINE(q'~    const MAXR = 120;~');
DBMS_OUTPUT.PUT_LINE(q'~    let names = [...seen.keys()].sort();~');
DBMS_OUTPUT.PUT_LINE(q'~    const cut = names.length > MAXR;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cut) names = [...seen.entries()].sort((a, b) => b[1] - a[1]).slice(0, MAXR).map((e) => e[0]).sort();~');
DBMS_OUTPUT.PUT_LINE(q'~    const rowsAll = ['table (global)'].concat(names);~');
DBMS_OUTPUT.PUT_LINE(q'~    const L = 190, R = 8, top = 4, bottom = 30, rh = 14;~');
DBMS_OUTPUT.PUT_LINE(q'~    const W = Math.max(200, width - L - R);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cw = Math.max(5, Math.min(22, W / runs.length));~');
DBMS_OUTPUT.PUT_LINE(q'~    const H = top + rowsAll.length * rh + bottom;~');
DBMS_OUTPUT.PUT_LINE(q'~    let s = '<svg width="' + (L + runs.length * cw + R) + '" height="' + H + '" role="img" aria-label="Which partitions each gather took">';~');
DBMS_OUTPUT.PUT_LINE(q'~    rowsAll.forEach((n, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (L - 8) + '" y="' + (top + i * rh + 11) + '" text-anchor="end"' + (i ? '' : ' style="fill:var(--ink-2)"') + '>' + esc(shortName(n, 26)) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((r, j) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const x = L + j * cw;~');
DBMS_OUTPUT.PUT_LINE(q'~      const cells = new Map();~');
DBMS_OUTPUT.PUT_LINE(q'~      r.glob.forEach((t) => cells.set(rowsAll[0], t));~');
DBMS_OUTPUT.PUT_LINE(q'~      r.parts.forEach((t) => cells.set(t.piece, t));~');
DBMS_OUTPUT.PUT_LINE(q'~      rowsAll.forEach((n, i) => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const t = cells.get(n);~');
DBMS_OUTPUT.PUT_LINE(q'~        const y = top + i * rh;~');
DBMS_OUTPUT.PUT_LINE(q'~        if (!t) { s += '<rect class="cell-empty" x="' + (x + 0.5) + '" y="' + (y + 0.5) + '" width="' + (cw - 1) + '" height="' + (rh - 1) + '"/>'; return; }~');
DBMS_OUTPUT.PUT_LINE(q'~        s += '<rect class="mark ' + (i ? typeClass(t) : t.status === 'FAILED' ? 'f-crit' : t.status !== 'COMPLETED' ? 'f-warn' : 'f-s1') + '" x="' + (x + 0.5) + '" y="' + (y + 0.5) + '" width="' + (cw - 1) + '" height="' + (rh - 1) + '" rx="2" data-href="#run/' + r.op.key + '" data-tip="' +~');
DBMS_OUTPUT.PUT_LINE(q'~          esc('<b>' + esc(i ? n : 'global statistics') + '</b><br>' + esc(opLabel(r.op)) + ', ' + esc(fmtT(r.op.start, true)) + '<br>' + esc(t.status.toLowerCase()) + ', ' + esc(fmtDur(t.secs)) + (t.hist.length ? '<br>Histograms: ' + esc(t.hist.join(', ')) : '')) + '"/>';~');
DBMS_OUTPUT.PUT_LINE(q'~      });~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    // one date label per ~70 px~');
DBMS_OUTPUT.PUT_LINE(q'~    const every = Math.max(1, Math.ceil(70 / cw));~');
DBMS_OUTPUT.PUT_LINE(q'~    let lastDay = '';~');
DBMS_OUTPUT.PUT_LINE(q'~    runs.forEach((r, j) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (j % every) return;~');
DBMS_OUTPUT.PUT_LINE(q'~      const d = fmtT(r.op.start).slice(5, 10);~');
DBMS_OUTPUT.PUT_LINE(q'~      s += '<text x="' + (L + j * cw + cw / 2) + '" y="' + (H - 8) + '" text-anchor="middle">' + esc(d === lastDay ? fmtClock(r.op.start) : d) + '</text>';~');
DBMS_OUTPUT.PUT_LINE(q'~      lastDay = d;~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const note = (cut ? 'The ' + MAXR + ' most recently gathered of ' + plural(seen.size, 'partition') + '. ' : '') +~');
DBMS_OUTPUT.PUT_LINE(q'~      (nparts > seen.size ? plural(nparts - seen.size, 'partition') + ' of ' + fmtN(nparts) + ' not gathered in the period.' : '');~');
DBMS_OUTPUT.PUT_LINE(q'~    return { svg: s + '</svg>', note: note };~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  let tabMetric = 'objects';~');
DBMS_OUTPUT.PUT_LINE(q'~  function viewTable(q, conStr, nameEnc) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const v = document.getElementById('view');~');
DBMS_OUTPUT.PUT_LINE(q'~    const name = nameEnc ? decodeURIComponent(nameEnc) : '';~');
DBMS_OUTPUT.PUT_LINE(q'~    const con = conStr ? Number(conStr) : null;~');
DBMS_OUTPUT.PUT_LINE(q'~    const text = (q.get('q') || '').toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~    let h = missingBox();~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<div class="filters tb-find"><input type="search" id="tb-q" placeholder="Find a table: owner.table" aria-label="Find a table" value="' + esc(text) + '"><span class="count" id="tb-n"></span></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!name) {~');
DBMS_OUTPUT.PUT_LINE(q'~      h += sec('Tables', 'Tables a gather touched in the period, with a table preference, or partitioned. Open one for its statistics, preferences, incremental setup and gather history.', '<div id="tb-list"></div>');~');
DBMS_OUTPUT.PUT_LINE(q'~      v.innerHTML = h;~');
DBMS_OUTPUT.PUT_LINE(q'~      const host = v.querySelector('#tb-list');~');
DBMS_OUTPUT.PUT_LINE(q'~      host._t = { sort: parseSort(q.get('s'), ['gathers', -1]), limit: 300 };~');
DBMS_OUTPUT.PUT_LINE(q'~      const box = v.querySelector('#tb-q');~');
DBMS_OUTPUT.PUT_LINE(q'~      const apply = () => {~');
DBMS_OUTPUT.PUT_LINE(q'~        const t = box.value.trim().toLowerCase();~');
DBMS_OUTPUT.PUT_LINE(q'~        const params = new URLSearchParams();~');
DBMS_OUTPUT.PUT_LINE(q'~        if (t) params.set('q', t);~');
DBMS_OUTPUT.PUT_LINE(q'~        const sp = sortParam(host._t.sort);~');
DBMS_OUTPUT.PUT_LINE(q'~        if (sp && sp !== '-gathers') params.set('s', sp);~');
DBMS_OUTPUT.PUT_LINE(q'~        setBaseHash('#table' + (params.toString() ? '?' + params.toString() : ''));~');
DBMS_OUTPUT.PUT_LINE(q'~        const all = tableIndex().filter((x) => !t || x.name.toLowerCase().includes(t));~');
DBMS_OUTPUT.PUT_LINE(q'~        const list = all.filter((x) => showOM || !x.om);~');
DBMS_OUTPUT.PUT_LINE(q'~        v.querySelector('#tb-n').innerHTML = esc(plural(list.length, 'table')) + omHint(all.length - list.length);~');
DBMS_OUTPUT.PUT_LINE(q'~        renderTable(host, {~');
DBMS_OUTPUT.PUT_LINE(q'~          rows: list, empty: 'No table matches.', href: (x) => tabHref(x.con, x.name), onSort: () => apply(),~');
DBMS_OUTPUT.PUT_LINE(q'~          cols: [~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'name', label: 'Table', cls: 'wrap', html: (x) => '<code>' + esc(x.name) + '</code>' + (CONS.size > 1 ? ' <span class="pill">' + esc(conName(x.con)) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'parts', label: 'Partitions', num: true, val: (x) => (x.tab ? x.tab.nparts : null), html: (x) => (x.tab && x.tab.ptype ? fmtN(x.tab.nparts || 0) + ' <span class="muted">' + esc(x.tab.ptype.toLowerCase()) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'inc', label: 'Incremental', val: (x) => { const p = x.prefs.find((p) => p.pref === 'INCREMENTAL'); return p ? p.value : null; },~');
DBMS_OUTPUT.PUT_LINE(q'~              html: (x) => { const p = x.prefs.find((p) => p.pref === 'INCREMENTAL'); return p ? '<code>' + esc(p.value) + '</code>' : (x.tab && x.tab.ptype ? '<span class="muted">' + esc(PREFS.get('INCREMENTAL') || '') + '</span>' : ''); } },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'rows', label: 'Rows', num: true, val: (x) => (x.tab ? x.tab.rows : null), html: (x) => (x.tab ? fmtN(x.tab.rows) : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'analyzed', label: 'Analyzed', cls: 't', val: (x) => (x.tab ? x.tab.analyzed : null), html: (x) => (x.tab ? (x.tab.analyzed ? esc(fmtT(x.tab.analyzed)) : '<span class="err">never</span>') : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'stale', label: 'Now', val: (x) => (x.tab ? (x.tab.stale ? 1 : 0) + (x.tab.pStale ? 1 : 0) : null),~');
DBMS_OUTPUT.PUT_LINE(q'~              html: (x) => (!x.tab ? '' : x.tab.stale ? sevBadge('warn', 'stale') : x.tab.pStale ? sevBadge('warn', plural(x.tab.pStale, 'stale partition')) : x.tab.pMissing ? sevBadge('warn', plural(x.tab.pMissing, 'partition') + ' without statistics') : x.tab.analyzed ? sevBadge('good', 'fresh') : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'gathers', label: 'Gathers', num: true, tip: 'Operations that touched the table or its partitions and indexes in the period', html: (x) => fmtN(x.gathers) },~');
DBMS_OUTPUT.PUT_LINE(q'~            { key: 'last', label: 'Last gather', cls: 't', val: (x) => (x.last ? x.last.start : null), html: (x) => (x.last ? esc(fmtT(x.last.start)) : '') }~');
DBMS_OUTPUT.PUT_LINE(q'~          ]~');
DBMS_OUTPUT.PUT_LINE(q'~        });~');
DBMS_OUTPUT.PUT_LINE(q'~      };~');
DBMS_OUTPUT.PUT_LINE(q'~      let qt;~');
DBMS_OUTPUT.PUT_LINE(q'~      box.oninput = () => { clearTimeout(qt); qt = setTimeout(apply, 180); };~');
DBMS_OUTPUT.PUT_LINE(q'~      apply();~');
DBMS_OUTPUT.PUT_LINE(q'~      return;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const key = conKey(con, name);~');
DBMS_OUTPUT.PUT_LINE(q'~    const tab = TABMAP.get(key) || null;~');
DBMS_OUTPUT.PUT_LINE(q'~    const owner = name.split('.')[0], tname = name.split('.').slice(1).join('.');~');
DBMS_OUTPUT.PUT_LINE(q'~    const runs = tableRuns(con, name);~');
DBMS_OUTPUT.PUT_LINE(q'~    const prefs = TPREFMAP.get(key) || [];~');
DBMS_OUTPUT.PUT_LINE(q'~    const pref = (n) => { const p = prefs.find((x) => x.pref === n); return p ? { v: p.value, src: 'table' } : { v: PREFS.get(n), src: 'global' }; };~');
DBMS_OUTPUT.PUT_LINE(q'~    const bl = BL.filter((b) => b.con === con && b.owner === owner && b.table === tname);~');
DBMS_OUTPUT.PUT_LINE(q'~    const near = NEAR.filter((b) => b.con === con && b.owner === owner && b.table === tname);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cols = COLS.filter((c) => c.con === con && c.name === name);~');
