DBMS_OUTPUT.PUT_LINE(q'~    const now = [];~');
DBMS_OUTPUT.PUT_LINE(q'~    if (bl.length) {~');
DBMS_OUTPUT.PUT_LINE(q'~      const cnt = {};~');
