DBMS_OUTPUT.PUT_LINE(q'~      now.push('<a href="#backlog?q=' + encodeURIComponent(name.toLowerCase()) + '">' + esc(plural(bl.length, 'object')) + ' need statistics</a>: ' + CAT_ORDER.filter((c) => cnt[c]).map((c) => sevBadge(CATS[c].sev, fmtN(cnt[c]) + ' ' + CATS[c].title.toLowerCase(), CATS[c].text)).join(' '));~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (near.length) now.push('<a href="#backlog?q=' + encodeURIComponent(name.toLowerCase()) + '">' + esc(plural(near.length, 'object')) + ' close to stale</a>');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (cols.length) now.push('<a href="#columns?q=' + encodeURIComponent(name.toLowerCase()) + '">' + esc(plural(cols.length, 'column')) + ' with doubtful statistics</a>');~');
DBMS_OUTPUT.PUT_LINE(q'~    facts.push(['Needs attention', now.length ? now.join('<br>') : '<span class="muted">nothing</span>']);~');
DBMS_OUTPUT.PUT_LINE(q'~    const cmd = fixScript([{ con: con, owner: owner, table: tname, locked: tab && tab.locked, cat: '' }]);~');
DBMS_OUTPUT.PUT_LINE(q'~    facts.push(['Gather', '<button type="button" class="copy" data-copy="' + esc(cmd) + '" data-tip="' + esc('<code>' + esc(cmd).replace(/\n/g, '<br>') + '</code><br><span class="muted">Click to copy</span>') + '">Copy statement</button>']);~');
DBMS_OUTPUT.PUT_LINE(q'~    const kv = '<dl class="kv">' + facts.map((f) => '<dt>' + f[0] + '</dt><dd>' + f[1] + '</dd>').join('') + '</dl>';~');
DBMS_OUTPUT.PUT_LINE(q'~    const KEYP = ['INCREMENTAL', 'INCREMENTAL_STALENESS', 'INCREMENTAL_LEVEL', 'PUBLISH', 'ESTIMATE_PERCENT', 'GRANULARITY', 'METHOD_OPT', 'STALE_PERCENT', 'CASCADE', 'DEGREE', 'CONCURRENT', 'NO_INVALIDATE', 'OPTIONS'];~');
DBMS_OUTPUT.PUT_LINE(q'~    const prefRows = KEYP.filter((p) => prefs.some((x) => x.pref === p) || PREFS.has(p)).map((p) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      const x = pref(p);~');
DBMS_OUTPUT.PUT_LINE(q'~      return '<tr' + (x.src === 'table' ? ' class="own"' : '') + '><td>' + esc(p) + '</td><td><code>' + esc(x.v == null ? '' : x.v) + '</code></td><td class="muted">' + (x.src === 'table' ? 'table' : con !== META.conId ? '<span data-tip="' + esc('Global preference of ' + esc(META.con) + ', the container the report ran in') + '">global*</span>' : 'global') + '</td></tr>';~');
DBMS_OUTPUT.PUT_LINE(q'~    }).concat(prefs.filter((x) => KEYP.indexOf(x.pref) < 0).map((x) => '<tr class="own"><td>' + esc(x.pref) + '</td><td><code>' + esc(x.value) + '</code></td><td class="muted">table</td></tr>'));~');
DBMS_OUTPUT.PUT_LINE(q'~    const prefTable = '<div class="tablewrap"><table class="prefs-t"><thead><tr><th>Preference</th><th>Value</th><th>Set at</th></tr></thead><tbody>' + prefRows.join('') + '</tbody></table></div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += '<section class="sec tb-head"><header><h2><code>' + esc(name) + '</code></h2>' + (CONS.size > 1 ? '<span class="pill">' + esc(conName(con)) + '</span>' : '') + '</header></section>';~');
DBMS_OUTPUT.PUT_LINE(q'~    h += sec('Incremental statistics', '', '<div class="surface"><div class="tablewrap"><table class="checks"><tbody>' +~');
