DBMS_OUTPUT.PUT_LINE(q'~      sec('Preferences in force', 'Table preferences override the global ones.', '<div class="surface">' + prefTable + '</div>') + '</div>';~');
DBMS_OUTPUT.PUT_LINE(q'~    if (runs.length) {~');
