DBMS_OUTPUT.PUT_LINE(q'~        { key: 'op', label: 'Run', cls: 'wrap', val: (r) => opLabel(r.op), html: (r) => esc(opLabel(r.op)) + (r.op.kind === 'auto' ? '' : ' <code>' + esc(opTarget(r.op)) + '</code>') + (r.op.job ? ' <span class="pill">' + esc(r.op.job) + '</span>' : '') },~');
