DBMS_OUTPUT.PUT_LINE(q'~        { key: 'glob', label: 'Global', num: true, tip: 'Time of the table-level (global) statistics', val: (r) => (r.glob.length ? r.glob.reduce((a, t) => a + (t.secs || 0), 0) : null),~');
DBMS_OUTPUT.PUT_LINE(q'~          html: (r) => (r.glob.length ? (r.glob.some((t) => t.status === 'FAILED') ? '<span class="err">failed</span> ' : '') + esc(fmtDur(r.glob.reduce((a, t) => a + (t.secs || 0), 0))) : '<span class="muted">no</span>') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'parts', label: 'Partitions', num: true, val: (r) => r.parts.length, html: (r) => (r.parts.length ? '<span data-tip="' + esc([...new Set(r.parts.map((t) => t.piece))].slice(0, 20).map(esc).join('<br>') + (r.parts.length > 20 ? '<br>+' + fmtN(r.parts.length - 20) + ' more' : '')) + '">' + fmtN(r.parts.length) + (nparts ? ' <span class="muted">of ' + fmtN(nparts) + '</span>' : '') + ', ' + esc(fmtDur(r.parts.reduce((a, t) => a + (t.secs || 0), 0))) + '</span>' : '') },~');
DBMS_OUTPUT.PUT_LINE(q'~        { key: 'idx', label: 'Indexes', num: true, val: (r) => r.idx.length, html: (r) => (r.idx.length ? fmtN(r.idx.length) : '') },~');
