DBMS_OUTPUT.PUT_LINE(q'~  // The run detail opens as a drawer over the view it was opened from.~');
DBMS_OUTPUT.PUT_LINE(q'~  let baseHash = null, renderedBase = null, closingByRoute = false, keepScroll = false;~');
DBMS_OUTPUT.PUT_LINE(q'~  function setBaseHash(hs) {~');
