DBMS_OUTPUT.PUT_LINE(q'~  function wireDrawer() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const d = document.getElementById('drawer');~');
DBMS_OUTPUT.PUT_LINE(q'~    d.addEventListener('close', () => {~');
DBMS_OUTPUT.PUT_LINE(q'~      hideTip();~');
DBMS_OUTPUT.PUT_LINE(q'~      if (!closingByRoute && location.hash.startsWith('#run/')) location.hash = baseHash || '#overview';~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    d.addEventListener('click', (e) => { if (e.target === d) d.close(); });~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function renderBase(raw) {~');
DBMS_OUTPUT.PUT_LINE(q'~    const qi = raw.indexOf('?');~');
DBMS_OUTPUT.PUT_LINE(q'~    const path = (qi < 0 ? raw : raw.slice(0, qi)).split('/');~');
DBMS_OUTPUT.PUT_LINE(q'~    const q = new URLSearchParams(qi < 0 ? '' : raw.slice(qi + 1));~');
DBMS_OUTPUT.PUT_LINE(q'~    const view = path[0] || 'overview';~');
DBMS_OUTPUT.PUT_LINE(q'~    document.querySelectorAll('.tabs a').forEach((a) => {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (a.getAttribute('data-v') === view || (view === 'overview' && a.getAttribute('data-v') === 'overview')) a.setAttribute('aria-current', 'page');~');
DBMS_OUTPUT.PUT_LINE(q'~      else a.removeAttribute('aria-current');~');
DBMS_OUTPUT.PUT_LINE(q'~    });~');
DBMS_OUTPUT.PUT_LINE(q'~    const keep = keepScroll ? window.scrollY : 0;~');
DBMS_OUTPUT.PUT_LINE(q'~    keepScroll = false;~');
DBMS_OUTPUT.PUT_LINE(q'~    renderedBase = raw;~');
DBMS_OUTPUT.PUT_LINE(q'~    baseHash = '#' + raw;~');
DBMS_OUTPUT.PUT_LINE(q'~    if (view === 'runs') viewRuns(q);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'backlog') viewBacklog(q);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'columns') viewColumns(q);~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'table') viewTable(q, path[1], path.slice(2).join('/'));~');
DBMS_OUTPUT.PUT_LINE(q'~    else if (view === 'config') viewConfig();~');
DBMS_OUTPUT.PUT_LINE(q'~    else viewOverview(path[1]);~');
DBMS_OUTPUT.PUT_LINE(q'~    if (!(view === 'overview' && path[1])) window.scrollTo(0, keep);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  function route() {~');
DBMS_OUTPUT.PUT_LINE(q'~    const raw = location.hash.replace(/^#/, '') || 'overview';~');
DBMS_OUTPUT.PUT_LINE(q'~    hideTip();~');
DBMS_OUTPUT.PUT_LINE(q'~    if (raw.startsWith('run/')) {~');
DBMS_OUTPUT.PUT_LINE(q'~      if (renderedBase === null) renderBase(baseHash ? baseHash.slice(1) : 'overview');~');
DBMS_OUTPUT.PUT_LINE(q'~      const p = raw.split('/');~');
DBMS_OUTPUT.PUT_LINE(q'~      openRun(p[1], p[2]);~');
DBMS_OUTPUT.PUT_LINE(q'~      return;~');
DBMS_OUTPUT.PUT_LINE(q'~    }~');
DBMS_OUTPUT.PUT_LINE(q'~    const d = document.getElementById('drawer');~');
DBMS_OUTPUT.PUT_LINE(q'~    if (d.open) { closingByRoute = true; d.close(); closingByRoute = false; }~');
DBMS_OUTPUT.PUT_LINE(q'~    if (raw !== renderedBase) renderBase(raw);~');
DBMS_OUTPUT.PUT_LINE(q'~  }~');
DBMS_OUTPUT.PUT_LINE(q'~  chrome();~');
DBMS_OUTPUT.PUT_LINE(q'~  wireDrawer();~');
DBMS_OUTPUT.PUT_LINE(q'~  wireGlobal();~');
DBMS_OUTPUT.PUT_LINE(q'~  window.addEventListener('hashchange', () => route());~');
DBMS_OUTPUT.PUT_LINE(q'~  route();~');
DBMS_OUTPUT.PUT_LINE(q'~})();~');
DBMS_OUTPUT.PUT_LINE(q'~</script>~');
END;
/
SET DEFINE ON
